window.__Q = (window.__Q || []).concat([
/* ===== Set 1: 企業会計の基礎（計算書類と企業会計原則） ===== */
{d:1,q:"会社法上の計算書類に関する次の記述のうち、正しいものを1つ選びなさい。",c:["計算書類は、貸借対照表・損益計算書・株主資本等変動計算書・個別注記表の4つで構成される。","計算書類には、キャッシュ・フロー計算書が含まれる。","計算書類は、上場会社だけが作成を義務づけられている。","計算書類には、事業報告と附属明細表が含まれる。","計算書類の主な目的は、投資者の保護である。"],a:0,e:"会社法の計算書類はB/S・P/L・株主資本等変動計算書・個別注記表の4つで、すべての株式会社が作成する。C/F計算書は金商法の財務諸表にだけ含まれ、目的は株主・債権者の保護。事業報告・附属明細書は計算書類とあわせて作る別の書類。"},
{d:1,q:"金融商品取引法に基づく財務諸表の構成として、正しいものはどれか。",c:["貸借対照表・損益計算書・株主資本等変動計算書・キャッシュ・フロー計算書・附属明細表","貸借対照表・損益計算書・個別注記表・事業報告","貸借対照表・損益計算書・製造原価報告書・附属明細書","貸借対照表・損益計算書・株主資本等変動計算書・個別注記表","貸借対照表・損益計算書・資金運用表・附属明細表"],a:0,e:"金商法の財務諸表はB/S・P/L・株主資本等変動計算書・C/F計算書・附属明細表。個別注記表・事業報告は会社法、資金運用表は財務分析の道具で財務諸表ではない。"},
{d:1,q:"企業会計原則の一般原則に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["保守主義の原則は、予想される損失だけでなく予想される利益も早めに計上することを求める。","真実性の原則は、企業の財政状態および経営成績について真実な報告を提供することを求める。","正規の簿記の原則は、すべての取引につき正確な会計帳簿を作成することを求める。","明瞭性の原則は、利害関係者が判断を誤らないよう会計事実を明瞭に表示することを求める。","単一性の原則は、目的別に形式の異なる財務諸表を作る場合も信頼できる同一の会計記録に基づくことを求める。"],a:0,e:"保守主義の原則は将来の危険に備えて慎重な処理をするもので、費用・損失は早めに、収益は確実になってから計上する。予想の利益を計上するのは未実現利益の計上であり、保守主義とは逆。"},
{d:1,q:"継続性の原則に関する記述として、正しいものはどれか。",c:["いったん採用した会計処理の原則・手続は、正当な理由がない限りみだりに変更してはならず、変更した場合は注記する。","いったん採用した会計処理の原則・手続は、いかなる理由があっても変更できない。","会計処理の原則・手続は、利益の状況に応じて毎期自由に選び直すことができる。","継続性の原則は、同業他社と同じ会計処理を採用することを求める。","継続性の原則は、複数の会計処理が認められている場合には適用されない。"],a:0,e:"継続性の原則は「みだりに変更しない」であって「絶対に変更できない」ではない。正当な理由があれば変更できるが、その旨と影響額を注記する。利益操作の排除と期間比較の確保が趣旨で、複数の処理が認められる場合にこそ意味を持つ。"},
{d:1,q:"真実性の原則における「真実」の意味として、正しいものはどれか。",c:["一般に公正妥当と認められた会計処理の中から選択した結果としての相対的な真実","唯一絶対の数値が存在するという絶対的な真実","税務署が認めた課税所得と一致するという真実","時価に基づいて評価した客観的な真実","経営者の判断を一切含まない機械的な真実"],a:0,e:"減価償却方法や棚卸資産の評価方法など複数の処理が認められているため、真実性の原則の真実は相対的真実と解される。絶対的真実と書く選択肢がひっかけ。"},
{d:1,q:"重要性の原則の位置づけとして、正しいものはどれか。",c:["企業会計原則の注解に定められ、重要性の乏しいものに簡便な処理を認める。","企業会計原則の一般原則の1つとして、7原則の中に含まれる。","損益計算書原則の中で、収益の認識基準として定められている。","会社法に定められ、大会社にのみ適用される。","重要性の乏しい項目でも、必ず本来の厳密な処理をしなければならないとする。"],a:0,e:"重要性の原則は一般原則ではなく注解1に定められる。重要性の乏しいものは簡便な処理（消耗品の買入時費用処理など）が認められ、その結果生じる簿外資産・簿外負債は正規の簿記の原則に反しない。"},
{d:1,q:"資本取引・損益取引区分の原則が直接求めていることとして、正しいものはどれか。",c:["資本剰余金と利益剰余金を混同してはならない。","資産と負債を相殺して表示してはならない。","当期の費用と収益を対応させなければならない。","会計処理の方法を毎期継続しなければならない。","将来の危険に備えて慎重な処理をしなければならない。"],a:0,e:"資本取引（増資など元手の増減）と損益取引（営業活動によるもうけ）を区別し、資本剰余金と利益剰余金を混同しないことを求める。相殺禁止は総額主義、対応は費用収益対応の原則。"},
{d:1,q:"単一性の原則の説明として、正しいものはどれか。",c:["株主総会用・税務用など目的により財務諸表の形式が異なっても、信頼できる単一の会計記録に基づいて作成し、事実の真実な表示をゆがめてはならない。","財務諸表は目的にかかわらず常に1種類の形式で作成しなければならない。","企業は1つの会計期間について1回だけ決算を行わなければならない。","会計帳簿は1冊の帳簿に集約しなければならない。","親会社と子会社は単一の会計方針を採用しなくてもよい。"],a:0,e:"単一性の原則は「形式多元・実質一元」。目的により形式が異なる財務諸表を作ることは認めるが、基礎となる会計記録は1つでなければならず、二重帳簿を禁止する。形式まで1つに限るのではない。"},
{d:1,q:"明瞭性の原則から直接要請される事項として、正しいものはどれか。",c:["重要な会計方針を財務諸表に注記すること","棚卸資産を取得原価で評価すること","減価償却を毎期規則的に行うこと","収益を実現の時点で認識すること","貸倒引当金を計上すること"],a:0,e:"明瞭性の原則は利害関係者が判断を誤らないよう会計事実を明瞭に表示することを求め、区分表示・総額表示・重要な会計方針の注記などがその具体化。他の選択肢は取得原価主義・費用配分・実現主義・発生主義の要請。"},
{d:1,q:"企業会計原則の一般原則（7原則）に該当しないものはどれか。",c:["重要性の原則","真実性の原則","継続性の原則","保守主義の原則","単一性の原則"],a:0,e:"一般原則は真実性・正規の簿記・資本取引と損益取引の区別・明瞭性・継続性・保守主義・単一性の7つ。重要性の原則は注解にあり、一般原則には数えない。"},
{d:1,q:"会計公準の組み合わせとして、正しいものはどれか。",c:["企業実体の公準・継続企業の公準・貨幣的評価の公準","真実性の公準・明瞭性の公準・継続性の公準","発生主義の公準・実現主義の公準・対応の公準","流動性の公準・安全性の公準・収益性の公準","取得原価の公準・時価の公準・償却原価の公準"],a:0,e:"会計公準は会計の前提条件で、企業実体（企業を所有者から独立した計算単位とみる）・継続企業（半永久的に続くと仮定し期間を区切る）・貨幣的評価（貨幣額で測定する）の3つ。発生主義などは公準ではなく損益計算の原則。"},
{d:1,q:"発生主義に関する記述として、正しいものはどれか。",c:["費用は現金の支出時ではなく、その発生の事実に基づいて計上する。","費用は現金を支払った時点で計上する。","収益は現金を受け取った時点で計上する。","費用も収益も契約を締結した時点で計上する。","発生主義は減価償却や引当金には適用されない。"],a:0,e:"発生主義は現金の収支ではなく経済的事実の発生に基づいて費用・収益を認識する考え方。現金の収支で計上するのは現金主義。減価償却・引当金・経過勘定はいずれも発生主義の産物。"},
{d:1,q:"実現主義に関する記述として、正しいものはどれか。",c:["収益は、財・サービスの提供と対価の受取（またはその確定）という実現の事実に基づいて計上する。","収益は、注文を受けた時点で計上する。","収益は、商品を仕入れた時点で計上する。","保有する土地の値上がり益は実現主義により当期の収益に計上する。","収益は、代金を全額回収した時点まで計上できない。"],a:0,e:"実現主義は財・サービスの引渡しと対価の成立をもって収益を認識する。値上がり益は未実現利益なので計上しない。代金の全額回収まで待つのは現金主義であり、掛売りでも引渡し時に収益を計上する。"},
{d:1,q:"費用収益対応の原則に関する記述として、正しいものはどれか。",c:["売上高と売上原価は個別的に対応し、販売費及び一般管理費は期間的に対応させる。","すべての費用は売上高と個別的に対応させなければならない。","費用と収益は対応させず、それぞれ現金の収支時に計上する。","費用収益対応の原則は、貸借対照表の資産と負債の対応を求める原則である。","販売費及び一般管理費は、売上原価に含めて売上高と対応させる。"],a:0,e:"費用収益対応の原則は、一期間の収益とそれを得るための費用を同一期間に対応させて利益を計算する原則。売上原価は商品ごとの個別的対応、販管費は期間的対応。"},
{d:1,q:"総額主義に関する次の記述のうち、正しいものを1つ選びなさい。",c:["同一の取引先に対する売掛金と買掛金であっても、相殺せずにそれぞれ総額で表示する。","受取利息と支払利息は、相殺して純額で損益計算書に表示する。","売上高は売上原価を差し引いた純額で表示する。","総額主義は損益計算書にのみ適用され、貸借対照表には適用されない。","総額主義により、貸倒引当金は売掛金と相殺して表示しなければならない。"],a:0,e:"総額主義は収益と費用、資産と負債を相殺せず総額で表示する原則で、P/L・B/Sの両方に適用される。貸倒引当金は控除形式で表示するが、これは総額主義の禁じる相殺ではなく評価勘定の表示。"},
{d:1,q:"法人税法における確定決算主義の説明として、正しいものはどれか。",c:["株主総会で確定した決算の当期純利益を基礎に、申告書で加算・減算の調整をして課税所得を計算する。","税法で計算した課税所得をそのまま損益計算書の当期純利益とする。","会計上の利益と課税所得は常に一致する。","課税所得は会計帳簿とは無関係に税務署が決定する。","確定決算主義とは、決算日から3か月以内に決算を確定する義務のことである。"],a:0,e:"法人税の課税所得は確定した決算利益に別表四で申告調整を加えて計算する（確定決算主義）。会計上の利益と課税所得は交際費の損金不算入などによりズレる。"},
{d:1,q:"会社法上の大会社の基準として、正しいものはどれか。",c:["資本金5億円以上または負債総額200億円以上","資本金1億円以上または負債総額100億円以上","資本金5億円以上かつ負債総額200億円以上","売上高100億円以上または従業員1,000人以上","上場していること"],a:0,e:"大会社は最終事業年度の貸借対照表で資本金5億円以上または負債総額200億円以上の株式会社で、会計監査人の設置が必要。「または」であって「かつ」ではない。"},
{d:1,q:"財務諸表の制度に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["金融商品取引法に基づく開示の主な目的は、株主・債権者の保護である。","会社法に基づく計算書類の主な目的は、株主・債権者の保護である。","金融商品取引法に基づく財務諸表は、公認会計士または監査法人の監査を受ける。","会社法・金融商品取引法・法人税法の3つの制度が相互に関連していることをトライアングル体制という。","中小企業の計算書類は、会計監査人の監査を受けていないことが多い。"],a:0,e:"金商法の目的は投資者の保護、会社法は株主・債権者の保護。目的を入れ替えた選択肢が誤り。監査を受けていない中小企業の決算書は、銀行員自身が妥当性を確かめる必要がある。"},
{d:1,q:"期間損益計算に関する次の記述のうち、正しいものを1つ選びなさい。",c:["減価償却・引当金の計上・経過勘定の処理は、いずれも発生主義に基づく手続である。","減価償却は現金主義に基づく手続である。","引当金の計上は実現主義に基づく手続である。","経過勘定の処理は総額主義に基づく手続である。","期間損益計算は継続企業の公準とは無関係である。"],a:0,e:"期間損益計算は継続企業を人為的に期間で区切ることから必要になり、費用を発生の事実で認識する発生主義により減価償却・引当金・経過勘定が生じる。"},
{d:1,q:"継続性の原則が必要とされる理由として、正しいものはどれか。",c:["経営者による利益操作を排除し、財務諸表の期間比較を可能にするため","税務当局の課税所得計算を簡素化するため","すべての企業の会計処理を同一にするため","時価評価による評価益の計上を認めるため","粉飾決算を発見した監査人の責任を免除するため"],a:0,e:"会計処理を毎期変えられると利益操作ができ、期間比較もできなくなる。継続性の原則はこの2つを防ぐためのもので、他社との統一を求める原則ではない。"},
{d:1,q:"保守主義の原則の限界に関する記述として、正しいものはどれか。",c:["過度に保守的な会計処理は、真実性の原則に反するため認められない。","保守主義の原則は真実性の原則に優先するため、いくら保守的でもよい。","保守主義の原則は、収益を早めに計上することを認める。","保守主義の原則は、税務上の損金算入限度額を定める原則である。","保守主義の原則は、貸倒引当金の計上を禁止する。"],a:0,e:"企業会計原則注解は、過度に保守的な処理は真実な報告をゆがめるとして認めない。保守主義は貸倒引当金の計上や低価法の根拠になる原則であり、収益は早めではなく確実になってから計上する。"},
{d:1,q:"正規の簿記の原則と簿外資産の関係として、正しいものはどれか。",c:["重要性の乏しい消耗品を買入時に費用処理して簿外資産が生じても、正規の簿記の原則に反しない。","簿外資産・簿外負債はいかなる場合も正規の簿記の原則に反する。","正規の簿記の原則は、単式簿記による帳簿作成を求める。","正規の簿記の原則は、帳簿を作成せず財務諸表を直接作成することを認める。","重要な固定資産を帳簿に記録しなくても、正規の簿記の原則には反しない。"],a:0,e:"正規の簿記の原則は網羅性・検証可能性・秩序性を備えた帳簿（実質的に複式簿記）を求めるが、重要性の原則による簡便処理から生じる簿外資産・負債は許容される。重要な資産の簿外化は当然に違反。"},
{d:1,q:"企業会計原則の構成として、正しいものはどれか。",c:["一般原則・損益計算書原則・貸借対照表原則の3部と注解","一般原則・連結原則・キャッシュ・フロー原則の3部","会計公準・会計基準・会計慣行の3部","資産原則・負債原則・純資産原則の3部と附則","損益計算書原則・貸借対照表原則の2部のみ"],a:0,e:"企業会計原則は一般原則・損益計算書原則・貸借対照表原則の3部からなり、注解で補足される。法令ではないが、すべての企業が従うべき規範とされる。"},
{d:1,q:"取得原価主義に関する記述として、正しいものはどれか。",c:["資産は原則として取得に要した支出額で記録し、有価証券の時価評価などは例外的な扱いである。","すべての資産は決算日の時価で評価しなければならない。","資産は取得原価と時価のいずれか高い方で評価する。","取得原価主義は負債にのみ適用される。","取得原価主義の下では、固定資産の減価償却は行わない。"],a:0,e:"日本の会計は取得原価主義が基本で、取得原価を耐用年数にわたり費用配分するのが減価償却。売買目的有価証券やその他有価証券の時価評価は例外。"},
{d:1,q:"ある会社の税引前当期純利益は1,000千円で、税務上、交際費の損金不算入額が120千円、受取配当金の益金不算入額が40千円ある。他に調整項目がない場合の課税所得はいくらか。",c:["1,080千円","920千円","1,160千円","840千円","1,000千円"],a:0,e:"課税所得＝会計上の利益＋加算（損金不算入）−減算（益金不算入）＝1,000＋120−40＝1,080千円。損金不算入は費用として認められない分を足し戻し、益金不算入は収益から外す。符号を逆にすると920千円になる。"},

/* ===== Set 2: 貸借対照表① 流動資産 ===== */
{d:2,q:"資産を流動と固定に分類する基準の適用順序として、正しいものはどれか。",c:["まず正常営業循環基準を適用し、循環の外にある項目に一年基準を適用する。","まず一年基準を適用し、1年超の項目に正常営業循環基準を適用する。","正常営業循環基準と一年基準のうち、企業が任意に選んだ一方だけを適用する。","すべての資産に一年基準のみを適用する。","すべての資産に正常営業循環基準のみを適用する。"],a:0,e:"営業循環内の項目（売上債権・棚卸資産・仕入債務など）は期間に関係なく流動とし、それ以外の項目に一年基準（決算日の翌日から1年以内か）を適用する。順番を逆にした選択肢が定番の誤り。"},
{d:2,q:"貸借対照表の分類に関する次の記述のうち、正しいものを1つ選びなさい。",c:["回収期限が決算日の翌日から1年を超える売掛金であっても、正常な営業循環内にあれば流動資産に表示する。","回収期限が1年を超える売掛金は、固定資産に表示する。","満期が決算日の翌日から2年後の定期預金は、流動資産に表示する。","返済期限が3年後の貸付金は、流動資産に表示する。","取引先の破綻により回収が1年超となる破産更生債権等は、流動資産に表示する。"],a:0,e:"売掛金は営業循環内なので期間にかかわらず流動資産。定期預金・貸付金は循環の外なので一年基準で1年超は固定（投資その他の資産）。破産更生債権等は循環から外れるため一年基準で判定し、1年超は投資その他の資産。"},
{d:2,q:"貸借対照表の配列法に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["流動性配列法は、電力・ガス業を含めすべての企業に強制されている。","流動性配列法では、資産は流動資産・固定資産・繰延資産の順に並べる。","流動性配列法では、負債は流動負債・固定負債の順に並べる。","固定性配列法は、固定資産の比重が大きい電力・ガス業などで採用されている。","企業会計原則では、流動性配列法が原則とされている。"],a:0,e:"流動性配列法が原則だが、電力・ガス業のように固定資産の割合が大きい業種では固定性配列法が採用される。「すべてに強制」が誤り。"},
{d:2,q:"貸借対照表の「現金」に含まれるものとして、正しいものはどれか。",c:["配当金領収証","収入印紙","自己振出の小切手","満期まで2年の定期預金","取引先からの借用証書"],a:0,e:"現金には通貨のほか他人振出小切手・送金小切手・郵便為替証書・配当金領収証・期限到来後の公社債利札など即時に換金できるものを含む。収入印紙は貯蔵品、自己振出小切手は当座預金の減少、2年の定期預金は長期預金（投資その他の資産）。"},
{d:2,q:"決算日の翌日から満期まで1年6か月ある定期預金の貸借対照表上の表示として、正しいものはどれか。",c:["投資その他の資産に「長期預金」として表示する。","流動資産に「現金及び預金」として表示する。","流動資産に「有価証券」として表示する。","繰延資産として表示する。","固定負債として表示する。"],a:0,e:"預金は営業循環の外なので一年基準で判定し、満期が1年超のものは投資その他の資産（長期預金）に表示する。「預金だから常に現金及び預金」というひっかけに注意。"},
{d:2,q:"当座借越（当座預金残高がマイナスになった状態）の貸借対照表上の表示として、正しいものはどれか。",c:["流動負債の短期借入金として表示する。","流動資産の現金及び預金からマイナス表示する。","固定負債の長期借入金として表示する。","流動負債の支払手形として表示する。","営業外費用として表示する。"],a:0,e:"当座借越は銀行からの一時的な借入と同じ性格なので、流動負債に短期借入金（または当座借越）として表示する。預金のマイナスとして相殺表示するのは総額主義に反する。"},
{d:2,q:"受取手形の割引・裏書譲渡に関する次の記述のうち、正しいものを1つ選びなさい。",c:["割引・裏書譲渡した手形は貸借対照表の受取手形から除外し、期日までは偶発債務として注記する。","割引した手形は、期日まで受取手形として貸借対照表に残す。","裏書譲渡した手形は、固定負債として貸借対照表に計上する。","割引した手形の割引料は、販売費及び一般管理費に計上する。","割引・裏書譲渡した手形は、引当金を設定して負債に計上しなければならない。"],a:0,e:"割引・裏書により手形債権は移転するのでB/Sから除外し、不渡時の遡求義務は偶発債務として注記する。割引料は手形売却損として営業外費用。可能性が高くない偶発債務は引当金ではなく注記。"},
{d:2,q:"手形を割り引いたときの割引料の損益計算書上の表示として、正しいものはどれか。",c:["営業外費用（手形売却損）","販売費及び一般管理費（支払手数料）","売上原価","特別損失","売上高からの控除"],a:0,e:"手形の割引は金融取引の性格を持つので、割引料は手形売却損として営業外費用に表示する。支払利息と同じ段に入る。"},
{d:2,q:"機械（固定資産）を売却した代金として受け取った約束手形の貸借対照表上の表示として、正しいものはどれか。",c:["営業外受取手形として、売上債権の受取手形とは区別して表示する。","受取手形に含めて売上債権として表示する。","売掛金に含めて表示する。","有価証券として表示する。","未収収益として表示する。"],a:0,e:"受取手形は営業取引（商品販売）から生じた手形に限る。固定資産の売却など営業外の取引で受け取った手形は営業外受取手形として区別し、売上債権回転期間の計算にも含めない。"},
{d:2,q:"電子記録債権（でんさい）の貸借対照表上の取り扱いとして、正しいものはどれか。",c:["受取手形と同様に売上債権として流動資産に表示する。","有価証券として流動資産に表示する。","投資その他の資産に表示する。","仕入債務として流動負債に表示する。","貸借対照表には計上せず注記する。"],a:0,e:"電子記録債権は電子債権記録機関に記録された金銭債権で、営業取引から生じたものは受取手形と同じ売上債権として流動資産に表示する。支払側は電子記録債務（仕入債務）。"},
{d:2,q:"貸倒引当金の貸借対照表上の表示として、正しいものはどれか。",c:["売掛金などの債権から控除する形式で表示する。","流動負債に表示する。","固定負債に表示する。","純資産の部に表示する。","販売費及び一般管理費に表示する。"],a:0,e:"貸倒引当金は債権の回収不能見込額を示す評価性引当金で、資産のマイナス項目として債権から控除する形式（または純額と注記）で表示する。負債に計上する負債性引当金と区別する。"},
{d:2,q:"貸倒引当金の見積りに関する次の記述のうち、誤っているものを1つ選びなさい。",c:["破産更生債権等は、過去の貸倒実績率を乗じて貸倒見積額を計算する。","一般債権は、過去の貸倒実績率など合理的な基準により貸倒見積額を計算する。","貸倒懸念債権は、担保の処分見込額や保証による回収見込額を控除した残額について個別に見積る。","破産更生債権等は、担保の処分見込額や保証による回収見込額を控除した残額の全額を引き当てる。","債権は一般債権・貸倒懸念債権・破産更生債権等の3つに区分して貸倒見積額を計算する。"],a:0,e:"破産更生債権等は経営破綻先への債権なので、担保・保証による回収見込額を除いた全額を引き当てる。貸倒実績率を使うのは一般債権。区分と方法を入れ替えた選択肢が誤り。"},
{d:2,q:"貸倒引当金繰入額の損益計算書上の表示として、正しいものはどれか。",c:["売上債権に対するものは販売費及び一般管理費、貸付金など営業外債権に対するものは営業外費用に表示する。","売上債権に対するものも貸付金に対するものも、すべて営業外費用に表示する。","売上債権に対するものも貸付金に対するものも、すべて特別損失に表示する。","売上債権に対するものは売上原価、貸付金に対するものは販売費及び一般管理費に表示する。","貸倒引当金繰入額は損益計算書に表示せず、純資産から直接控除する。"],a:0,e:"繰入額は対象債権の性格に応じて分ける。営業活動から生じた売上債権分は販管費、営業外の貸付金分は営業外費用。すべて同じ区分にする選択肢が誤り。"},
{d:2,q:"期末の売掛金が5,000千円、受取手形が3,000千円で、これらに対し貸倒実績率2%で貸倒引当金を設定する。貸倒引当金の期末残高（繰入前）が100千円であるとき、差額補充法による当期の貸倒引当金繰入額はいくらか。",c:["60千円","160千円","100千円","40千円","260千円"],a:0,e:"設定額＝（5,000＋3,000）×2%＝160千円。差額補充法では残高100千円との差額だけを繰り入れるので160−100＝60千円。設定額そのもの（160千円）を答えると誤り。洗替法なら戻入100・繰入160だが期末残高は同じ160。"},
{d:2,q:"有価証券の分類と評価に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["満期保有目的の債券は、期末に時価で評価し、評価差額を当期の損益に計上する。","売買目的有価証券は、期末に時価で評価し、評価差額を当期の損益に計上する。","子会社株式および関連会社株式は、取得原価で評価する。","その他有価証券は、期末に時価で評価し、評価差額は純資産の部に計上する。","満期保有目的の債券を額面より低い価額で取得した場合、差額が金利調整と認められるときは償却原価法を適用する。"],a:0,e:"満期保有目的の債券は満期まで保有するので時価変動は関係なく、取得原価または償却原価で評価する。時価評価して損益に計上するのは売買目的有価証券。"},
{d:2,q:"その他有価証券の期末評価差額の取り扱いとして、正しいものはどれか。",c:["税効果を適用したうえで、純資産の部に「その他有価証券評価差額金」として計上する。","営業外損益として当期の損益に計上する。","特別損益として当期の損益に計上する。","評価差額は計上せず、取得原価のまま据え置く。","評価益は当期の利益に、評価損は純資産に計上する。"],a:0,e:"その他有価証券は時価評価するが、売却の予定がないため評価差額はP/Lを通さず純資産に直入する（全部純資産直入法）。部分純資産直入法では評価損だけを損益にするので、最後の選択肢は逆。"},
{d:2,q:"子会社株式・関連会社株式の期末評価として、正しいものはどれか。",c:["取得原価で評価する（時価が著しく下落し回復見込みがない場合を除く）。","時価で評価し、評価差額を営業外損益に計上する。","時価で評価し、評価差額を純資産の部に計上する。","償却原価法で評価する。","持分法により毎期評価替えする。"],a:0,e:"子会社・関連会社株式は支配や影響力の行使を目的とし売却を予定しないので、個別財務諸表では取得原価で評価する。市場価格が著しく下落して回復見込みがなければ減損する。持分法は連結財務諸表での処理。"},
{d:2,q:"市場価格のある有価証券の減損処理（強制評価減）に関する記述として、正しいものはどれか。",c:["時価が著しく下落し（おおむね50%程度以上）、回復する見込みがない場合には、分類にかかわらず時価まで評価減し、差額を当期の損失とする。","時価が取得原価を少しでも下回れば、直ちに減損処理を行う。","減損処理は売買目的有価証券にのみ適用される。","減損処理で計上した評価損は、翌期に時価が回復すれば戻し入れる。","時価が30%程度下落すれば、回復の見込みにかかわらず必ず減損処理する。"],a:0,e:"減損処理は「著しい下落（50%程度以上が目安）」と「回復見込みなし」の両方を満たすときに行い、満期保有目的・子会社株式・その他有価証券にも適用される。減損後の簿価は戻し入れない。"},
{d:2,q:"満期保有目的の債券のうち、決算日の翌日から1年以内に満期が到来するものの貸借対照表上の表示として、正しいものはどれか。",c:["流動資産の「有価証券」に表示する。","投資その他の資産の「投資有価証券」に表示する。","流動資産の「現金及び預金」に表示する。","無形固定資産に表示する。","繰延資産に表示する。"],a:0,e:"有価証券は営業循環の外なので一年基準で判定する。満期保有目的の債券は通常は投資有価証券（固定）だが、1年内に満期が来るものは流動資産の有価証券に振り替える。"},
{d:2,q:"額面10,000千円の社債を9,500千円で取得し、満期保有目的の債券として保有している。取得から満期まで5年で、額面との差額は金利調整と認められる。償却原価法（定額法）による取得後1年目末の帳簿価額はいくらか。",c:["9,600千円","9,500千円","10,000千円","9,700千円","9,400千円"],a:0,e:"差額10,000−9,500＝500千円を5年で配分するので毎期100千円ずつ帳簿価額に加算する。1年目末は9,500＋100＝9,600千円。加算額は有価証券利息（営業外収益）に計上する。"},
{d:2,q:"棚卸資産の払出単価の計算方法に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["後入先出法は、現在も棚卸資産の評価方法として認められている。","先入先出法は、先に仕入れたものから先に払い出すと仮定して払出単価を計算する。","移動平均法は、仕入のつど平均単価を計算し直す。","総平均法は、一定期間の受入総額を受入総数量で割って平均単価を計算する。","売価還元法は、売価に原価率を乗じて期末棚卸資産の原価を計算する方法である。"],a:0,e:"後入先出法は2010年以後廃止され選択できない。認められるのは個別法・先入先出法・平均原価法（総平均法・移動平均法）・売価還元法。"},
{d:2,q:"通常の販売目的で保有する棚卸資産の期末評価に関する記述として、正しいものはどれか。",c:["取得原価と正味売却価額を比較し、正味売却価額が下回る場合は正味売却価額まで評価減し、評価損は原則として売上原価に計上する。","取得原価と正味売却価額のいずれか高い方で評価する。","常に取得原価で評価し、時価の下落は考慮しない。","評価損は原則として特別損失に計上する。","正味売却価額とは、売価に見積販売直接経費を加算した金額である。"],a:0,e:"棚卸資産は取得原価と正味売却価額（売価−見積追加製造原価−見積販売直接経費）のいずれか低い方で評価する。評価損は原則売上原価で、臨時かつ多額の場合に限り特別損失。"},
{d:2,q:"商品の期首在庫は20個（@500円）、当期仕入は30個（@600円）で、期末在庫は15個であった。先入先出法による当期の売上原価はいくらか。",c:["19,000円","18,500円","20,500円","9,000円","28,000円"],a:0,e:"先入先出法では期末在庫は後から仕入れた分で構成されるので、期末＝15個×600＝9,000円。売上原価＝期首10,000＋仕入18,000−期末9,000＝19,000円。期末在庫額（9,000円）を答えないこと。"},
{d:2,q:"経過勘定等に関する次の記述のうち、正しいものを1つ選びなさい。",c:["前受収益は、まだ提供していない役務の対価を先に受け取ったものであり、負債に表示する。","前払費用は、役務の提供を受けたがまだ支払っていない費用であり、負債に表示する。","未収収益は、役務を提供済みで未回収の収益であり、負債に表示する。","未払費用は、役務の提供を受けていない期間の費用を先に支払ったものであり、資産に表示する。","前渡金は、継続的な役務提供契約の前払いであり、経過勘定の前払費用と同じものである。"],a:0,e:"経過勘定は費用なら前払（資産）・未払（負債）、収益なら未収（資産）・前受（負債）。前渡金は商品代金の前払いで営業循環内の債権であり、役務の期間配分である前払費用とは別物。"},
{d:2,q:"棚卸資産の評価損と棚卸減耗損の表示に関する記述として、正しいものはどれか。",c:["収益性の低下による評価損は原則として売上原価に計上し、原価性のない棚卸減耗損は営業外費用または特別損失に計上する。","評価損は常に特別損失に計上し、棚卸減耗損は常に売上原価に計上する。","評価損も棚卸減耗損も、常に販売費及び一般管理費に計上する。","評価損は純資産の部に直接計上する。","棚卸減耗損は原価性の有無にかかわらず、常に営業外費用に計上する。"],a:0,e:"評価損は原則売上原価（臨時かつ多額なら特別損失）。棚卸減耗損は通常発生する程度（原価性あり）なら売上原価または販管費、異常な発生（原価性なし）なら営業外費用または特別損失。"},

/* ===== Set 3: 貸借対照表② 固定資産・繰延資産 ===== */
{d:3,q:"機械装置の取得原価に含めるものとして、正しいものはどれか。",c:["据付費・試運転費","取得後に発生した修繕費","毎年課される固定資産税","取得のための借入金の支払利息（原則）","操作する従業員の研修費"],a:0,e:"取得原価＝購入代価＋使用できる状態にするまでの付随費用（引取運賃・据付費・試運転費など）。修繕費・固定資産税は期間費用、借入金の利息は原則として取得原価に含めない。"},
{d:3,q:"資本的支出と収益的支出に関する次の記述のうち、正しいものを1つ選びなさい。",c:["耐用年数を延長させる改良のための支出は資本的支出として資産の取得原価に加算し、原状回復のための支出は収益的支出として修繕費に計上する。","耐用年数を延長させる改良のための支出は、すべて修繕費として費用処理する。","原状回復のための支出は資本的支出として資産に計上する。","資本的支出も収益的支出も、すべて繰延資産に計上する。","修繕費を資産計上しても、当期の利益には影響しない。"],a:0,e:"資本的支出は資産の価値増加・耐用年数延長をもたらすので資産計上し減価償却で費用化する。収益的支出は当期の費用。修繕費を資産に計上すると当期の費用が減って利益が水増しされる。"},
{d:3,q:"建設仮勘定に関する記述として、正しいものはどれか。",c:["建設中の固定資産への支出を集計する有形固定資産の科目で、完成して事業の用に供するまで減価償却を行わない。","建設中の固定資産への支出を集計する科目で、支出のつど減価償却を開始する。","建設会社の仕掛工事を表す棚卸資産の科目である。","建設のための借入金を表す固定負債の科目である。","建設のための支出を表す繰延資産の科目である。"],a:0,e:"建設仮勘定は有形固定資産だが、まだ使用していないので償却しない。完成時に建物などへ振り替えてから償却を始める。土地も非償却資産。"},
{d:3,q:"減価償却を行わない資産として、正しいものはどれか。",c:["土地","建物","機械装置","ソフトウェア","のれん"],a:0,e:"土地は使用や時の経過で価値が減らないので減価償却しない。建設仮勘定・借地権・電話加入権も非償却。建物・機械は有形固定資産、ソフトウェア・のれんは無形固定資産でいずれも償却する。"},
{d:3,q:"取得原価2,400千円、残存価額ゼロ、耐用年数8年の備品を当期の10月1日に取得して使用を開始した。決算日は3月31日で、定額法により月割計算する場合の当期の減価償却費はいくらか。",c:["150千円","300千円","75千円","200千円","600千円"],a:0,e:"年間償却費＝2,400÷8＝300千円。期中取得なので使用月数6か月（10月〜3月）で月割し、300×6/12＝150千円。年額のまま300千円とするのが典型的な誤り。"},
{d:3,q:"取得原価1,000千円、残存価額ゼロの機械を定率法（償却率0.25）で償却している。2年目の減価償却費はいくらか（1年目は期首に取得し1年分償却済み）。",c:["187.5千円","250千円","125千円","62.5千円","200千円"],a:0,e:"1年目＝1,000×0.25＝250千円。2年目は期首帳簿価額（1,000−250＝750千円）に償却率を掛けて750×0.25＝187.5千円。取得原価に掛け続けて250千円とするのがひっかけ。"},
{d:3,q:"定率法の特徴として、正しいものはどれか。",c:["初期の減価償却費が大きく、年数の経過とともに償却費が減少する。","毎期同額の減価償却費を計上する。","利用量に比例して減価償却費を計上する。","初期の減価償却費が小さく、年数の経過とともに償却費が増加する。","残存価額を取得原価から控除した額を耐用年数で割って償却費を計算する。"],a:0,e:"定率法は期首帳簿価額に一定率を掛けるので、償却費は逓減する。早期に費用化するため保守的で、定額法より初期の利益は小さくなる。毎期同額は定額法、利用量比例は生産高比例法。"},
{d:3,q:"生産高比例法の適用が適切とされる資産として、正しいものはどれか。",c:["鉱業用設備・航空機・自動車など、総利用可能量が物理的に確定できる資産","本社ビルなどの建物","のれん","土地","特許権"],a:0,e:"生産高比例法は総利用可能量に対する当期利用量の割合で償却するので、走行距離や採掘量など利用量が測定できる資産に適する。建物は定額法、のれん・特許権は定額法での償却が一般的。"},
{d:3,q:"減価償却累計額の表示に関する記述として、正しいものはどれか。",c:["間接法では、有形固定資産の取得原価から減価償却累計額を控除する形式で表示する。","間接法では、減価償却累計額を固定負債に表示する。","直接法では、減価償却累計額を純資産の部に表示する。","減価償却累計額は、損益計算書の販売費及び一般管理費に表示する。","無形固定資産は、減価償却累計額を控除する形式（間接法）で表示するのが一般的である。"],a:0,e:"間接法は減価償却累計額を資産の控除項目として表示し、取得原価が分かる。直接法は資産から直接減額し純額表示。無形固定資産は直接法が一般的。P/Lに載るのは当期の減価償却費。"},
{d:3,q:"減価償却に関する次の記述のうち、正しいものを1つ選びなさい。",c:["減価償却は、固定資産の取得原価を耐用年数にわたって計画的・規則的に費用配分する手続である。","減価償却は、固定資産を決算日の時価に評価替えする手続である。","減価償却費は現金の支出を伴う費用である。","工場の機械の減価償却費は、販売費及び一般管理費に計上する。","土地は耐用年数を見積って定額法で減価償却する。"],a:0,e:"減価償却は費用配分の手続であり、時価評価ではない。支出を伴わない費用なのでC/F計算書（間接法）では利益に加算する。製造用設備の償却費は製造原価、営業・本社用は販管費。土地は非償却。"},
{d:3,q:"減価償却方法を定率法から定額法に変更する場合の取り扱いとして、正しいものはどれか。",c:["会計方針の変更にあたるため、正当な理由が必要であり、変更の内容と影響額を注記する。","減価償却方法は毎期自由に変更でき、注記も不要である。","減価償却方法の変更は禁止されており、いかなる理由があっても変更できない。","減価償却方法の変更は会計上の見積りの変更ではなく、財務諸表に影響しない。","減価償却方法を変更した場合、過去の減価償却費をすべて再計算して訂正しなければならない。"],a:0,e:"償却方法の変更は会計方針の変更で、継続性の原則から正当な理由が必要。利益が出ない年に償却方法を変えて償却費を減らしていないか、銀行員は注記を確認する。"},
{d:3,q:"固定資産の減損会計の手順に関する記述として、正しいものはどれか。",c:["減損の兆候がある資産について、割引前将来キャッシュ・フローの総額が帳簿価額を下回る場合に減損を認識し、帳簿価額を回収可能価額まで減額する。","減損の兆候の有無にかかわらず、すべての固定資産について毎期減損損失を計算する。","割引後将来キャッシュ・フローが帳簿価額を下回る場合に減損を認識し、割引前将来キャッシュ・フローまで減額する。","減損損失は、帳簿価額と取得原価との差額として計算する。","減損の兆候がある資産は、兆候があった時点で直ちに帳簿価額をゼロにする。"],a:0,e:"減損会計は「兆候→認識→測定」の3段階。認識の判定は割引前CFで行い、測定は回収可能価額（正味売却価額と使用価値の高い方）で行う。認識と測定の基準を入れ替えた選択肢に注意。"},
{d:3,q:"減損会計における回収可能価額の定義として、正しいものはどれか。",c:["正味売却価額と使用価値のいずれか高い方の金額","正味売却価額と使用価値のいずれか低い方の金額","割引前将来キャッシュ・フローの総額","取得原価から減価償却累計額を控除した金額","正味売却価額と使用価値の平均額"],a:0,e:"回収可能価額は正味売却価額（時価−処分費用）と使用価値（将来CFの割引現在価値）の高い方。売却か継続使用か有利な方で投資を回収できると考えるため「高い方」。"},
{d:3,q:"ある工場設備（帳簿価額800千円）に減損の兆候があり、割引前将来キャッシュ・フローの総額は700千円、正味売却価額は500千円、使用価値は550千円と見積られた。計上すべき減損損失はいくらか。",c:["250千円","300千円","100千円","0円","150千円"],a:0,e:"割引前CF700＜帳簿価額800なので減損を認識する。回収可能価額＝max（500, 550）＝550千円。減損損失＝800−550＝250千円。正味売却価額500を使うと300千円になり誤り。"},
{d:3,q:"減損損失に関する次の記述のうち、正しいものを1つ選びなさい。",c:["減損損失は特別損失に計上し、減損後は減損後の帳簿価額を基礎に減価償却を行う。","減損損失は販売費及び一般管理費に計上する。","減損損失を計上した後、収益性が回復した場合には減損損失を戻し入れる。","減損損失を計上した資産は、以後減価償却を行わない。","減損損失は営業外費用に計上する。"],a:0,e:"減損損失は臨時・巨額の損失なので特別損失。日本基準では減損損失の戻入れは行わず、減損後の簿価を基礎に償却を続ける。"},
{d:3,q:"のれんの会計処理として、正しいものはどれか。",c:["20年以内のその効果の及ぶ期間にわたって規則的に償却し、償却額は販売費及び一般管理費に計上する。","償却せず、毎期時価で評価替えする。","5年以内に定額法で償却し、償却額は営業外費用に計上する。","取得した期に全額を特別損失として処理する。","自社で創設したのれんも資産として計上できる。"],a:0,e:"のれんは買収対価が受け入れた純資産を超える額で、無形固定資産として20年以内で規則的に償却し、償却額は販管費。自己創設のれんは計上できない。償却せず減損テストのみ行うのはIFRSの扱い。"},
{d:3,q:"企業を買収した際に、取得価額が受け入れた純資産（時価）を下回った場合の差額（負ののれん）の処理として、正しいものはどれか。",c:["発生した事業年度の特別利益（負ののれん発生益）として処理する。","無形固定資産に計上し、20年以内で償却する。","固定負債に計上し、20年以内で取り崩す。","純資産の部の資本剰余金に計上する。","営業外収益として5年間で均等に計上する。"],a:0,e:"負ののれんは発生時に一括して特別利益に計上する。正ののれん（資産計上・償却）との対比で問われる。"},
{d:3,q:"ソフトウェアの会計処理に関する記述として、正しいものはどれか。",c:["自社利用目的のソフトウェアは、将来の収益獲得または費用削減が確実な場合に資産計上し、5年以内で償却する。","自社利用目的のソフトウェアの制作費は、すべて発生時に費用処理する。","市場販売目的のソフトウェアは、研究開発段階の支出も含めて全額資産計上する。","ソフトウェアは有形固定資産に計上する。","自社利用目的のソフトウェアは、20年以内で償却する。"],a:0,e:"ソフトウェアは無形固定資産。自社利用は要件を満たせば資産計上し5年以内で償却、市場販売目的は研究開発終了後の制作費を資産計上し3年以内で償却。研究開発段階の支出は研究開発費として費用処理。"},
{d:3,q:"研究開発費の会計処理として、正しいものはどれか。",c:["発生時に全額費用として処理し、資産計上は認められない。","繰延資産に計上し、5年以内で償却する。","無形固定資産に計上し、成果が出た時点から償却する。","成功した研究開発費のみ資産計上し、失敗したものは費用処理する。","製造業の場合は棚卸資産に計上する。"],a:0,e:"研究開発費は成果の不確実性が高いため、発生時に全額費用処理（販管費または製造原価）。繰延資産の「開発費」（市場開拓等）とは別物であり、混同させる選択肢が定番。"},
{d:3,q:"投資その他の資産に表示される科目として、正しいものはどれか。",c:["長期貸付金","建設仮勘定","ソフトウェア","短期貸付金","開業費"],a:0,e:"投資その他の資産は投資有価証券・関係会社株式・長期貸付金・長期前払費用・繰延税金資産など。建設仮勘定は有形固定資産、ソフトウェアは無形固定資産、短期貸付金は流動資産、開業費は繰延資産。"},
{d:3,q:"繰延資産として計上できる5項目の組み合わせとして、正しいものはどれか。",c:["創立費・開業費・株式交付費・社債発行費等・開発費","創立費・開業費・研究開発費・広告宣伝費・試験研究費","創立費・開業費・株式交付費・社債発行費等・研究開発費","のれん・特許権・商標権・借地権・ソフトウェア","前払費用・長期前払費用・繰延税金資産・保証金・敷金"],a:0,e:"繰延資産は創立費・開業費・株式交付費・社債発行費等・開発費の5つ。研究開発費は発生時費用処理で繰延資産にできない。原則は支出時の費用処理で、繰延資産計上は容認。"},
{d:3,q:"繰延資産の償却期間に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["株式交付費は、5年以内に償却する。","創立費は、5年以内に償却する。","開業費は、5年以内に償却する。","開発費は、5年以内に償却する。","社債発行費等は、社債の償還期間内に償却する。"],a:0,e:"株式交付費の償却期間は3年以内。創立費・開業費・開発費は5年以内、社債発行費等は償還期間内（利息法が原則、定額法も可）。年数を入れ替える出題が多い。"},
{d:3,q:"ファイナンス・リース取引の判定基準に関する記述として、正しいものはどれか。",c:["中途解約不能（ノンキャンセラブル）かつフルペイアウトのリースで、リース料総額の現在価値が見積現金購入価額のおおむね90%以上、またはリース期間が経済的耐用年数のおおむね75%以上であれば該当する。","リース期間が1年以上であれば、すべてファイナンス・リース取引となる。","リース料総額の現在価値が見積現金購入価額のおおむね75%以上、またはリース期間が経済的耐用年数のおおむね90%以上であれば該当する。","中途解約が可能なリースは、すべてファイナンス・リース取引となる。","リース資産を貸借対照表に計上しないリースをファイナンス・リース取引という。"],a:0,e:"ファイナンス・リースはノンキャンセラブルとフルペイアウトの2要件で、具体的判定は現在価値基準90%・経済的耐用年数基準75%。数字を入れ替えた選択肢が誤り。借手は売買処理でリース資産・リース債務を計上する。"},
{d:3,q:"所有権移転外ファイナンス・リース取引の借手の会計処理として、正しいものはどれか。",c:["リース資産とリース債務を計上し、リース期間を耐用年数、残存価額ゼロとして減価償却する。","支払リース料をそのまま費用処理し、リース資産は計上しない。","リース資産を計上し、自己所有の固定資産と同じ耐用年数・残存価額で減価償却する。","リース料総額を一括して支払時に特別損失とする。","リース資産のみ計上し、リース債務は注記にとどめる。"],a:0,e:"所有権移転外ファイナンス・リースは売買処理し、リース期間定額法（残存価額ゼロ）で償却する。自己所有と同じ方法で償却するのは所有権移転ファイナンス・リース。賃貸借処理はオペレーティング・リース。"},
{d:3,q:"国庫補助金を受けて取得した固定資産について圧縮記帳（直接減額方式）を行った場合の影響として、正しいものはどれか。",c:["固定資産の取得原価が補助金相当額だけ減額されるため、以後の減価償却費が小さくなる。","固定資産の取得原価が補助金相当額だけ増額されるため、以後の減価償却費が大きくなる。","補助金相当額が繰延資産に計上され、5年間で償却される。","補助金相当額が固定負債に計上され、償却は行われない。","圧縮記帳を行うと、補助金に対する課税が永久に免除される。"],a:0,e:"圧縮記帳は補助金や保険差益による課税を繰り延べる制度。直接減額方式では取得原価から補助金相当額を減額するので、以後の償却費が小さくなり、その分だけ将来の利益（課税所得）が増える。免税ではなく課税の繰延べ。"},

/* ===== Set 4: 貸借対照表③ 負債・純資産 ===== */
{d:4,q:"流動負債に表示される科目の組み合わせとして、正しいものはどれか。",c:["買掛金・短期借入金・賞与引当金","社債・長期借入金・退職給付引当金","資本金・利益準備金・自己株式","売掛金・前払費用・貸倒引当金","繰延税金負債・資産除去債務・長期預り金"],a:0,e:"買掛金は営業循環内、短期借入金・賞与引当金は1年内に支払・取崩となるため流動負債。社債・長期借入金・退職給付引当金・繰延税金負債・資産除去債務は固定負債。"},
{d:4,q:"長期借入金のうち決算日の翌日から1年以内に返済期限が到来する部分の表示として、正しいものはどれか。",c:["「1年内返済予定の長期借入金」として流動負債に表示する。","長期借入金に含めたまま固定負債に表示する。","短期借入金に含めて表示し、注記は不要である。","純資産の部に振り替える。","営業外費用に表示する。"],a:0,e:"借入金は営業循環の外なので一年基準で判定し、1年内返済分は流動負債へ振り替える。流動比率の計算に影響するので、銀行員は返済スケジュールを確認する。"},
{d:4,q:"機械の購入代金を約束手形で支払った場合の表示として、正しいものはどれか。",c:["営業外支払手形（設備支払手形）として、仕入債務の支払手形と区別して表示する。","支払手形に含めて仕入債務として表示する。","買掛金に含めて表示する。","長期借入金として固定負債に表示する。","未払費用として表示する。"],a:0,e:"支払手形は営業取引（仕入）から生じた手形に限る。設備購入など営業外の手形は営業外支払手形として区別し、仕入債務回転期間の計算にも含めない。"},
{d:4,q:"買掛金・未払金・未払費用の区別に関する記述として、正しいものはどれか。",c:["買掛金は仕入代金の未払い、未払金は固定資産の購入代金など確定した営業外の債務の未払い、未払費用は継続的な役務提供に対する経過勘定である。","買掛金は固定資産の購入代金の未払い、未払金は仕入代金の未払いである。","未払費用は確定した債務であり、未払金は経過勘定である。","買掛金と未払金はいずれも固定負債に表示する。","未払費用は資産の部に表示する。"],a:0,e:"買掛金は仕入債務、未払金は営業外取引で確定した債務、未払費用は未払利息・未払給料など時間の経過に伴う経過勘定。いずれも通常は流動負債。"},
{d:4,q:"額面100,000千円の社債を97,000千円で発行し、償還期間は5年である。額面との差額が金利調整と認められ、償却原価法（定額法）を適用する場合、発行後1年目末の社債の帳簿価額はいくらか。",c:["97,600千円","97,000千円","100,000千円","98,500千円","96,400千円"],a:0,e:"差額3,000千円を5年で配分し、毎期600千円ずつ帳簿価額に加算する。1年目末は97,000＋600＝97,600千円。加算額は社債利息（営業外費用）に計上し、満期に額面100,000千円になる。"},
{d:4,q:"引当金の計上要件に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["将来の費用・損失の発生の可能性が少しでもあれば、引当金を計上しなければならない。","将来の特定の費用または損失であることが必要である。","その発生が当期以前の事象に起因していることが必要である。","その金額を合理的に見積ることができることが必要である。","要件を満たす場合、当期の負担に属する金額を当期の費用または損失として繰り入れる。"],a:0,e:"引当金の4要件は「将来の特定の費用・損失」「当期以前の事象に起因」「発生の可能性が高い」「金額を合理的に見積れる」。可能性が「高い」ことが必要で、少しでもあれば計上するのは誤り。可能性が低いものは偶発債務の注記。"},
{d:4,q:"評価性引当金に該当するものとして、正しいものはどれか。",c:["貸倒引当金","賞与引当金","退職給付引当金","製品保証引当金","修繕引当金"],a:0,e:"評価性引当金は資産の控除項目となる引当金で、貸倒引当金がその代表（実質的に唯一）。賞与・退職給付・製品保証・修繕引当金は負債の部に計上する負債性引当金。"},
{d:4,q:"修繕引当金の性格として、正しいものはどれか。",c:["自社の資産の修繕に備えるもので、相手方に対する法的債務ではないが、負債性引当金として負債の部に計上する。","従業員に対する法的債務であり、債務性のある引当金である。","資産の控除項目として表示する評価性引当金である。","純資産の部に計上する積立金である。","偶発債務として注記のみ行い、貸借対照表には計上しない。"],a:0,e:"修繕引当金・特別修繕引当金は相手方への債務がない「債務でない引当金」だが、負債の部に計上する。賞与・退職給付・製品保証引当金は条件付債務として債務性がある。"},
{d:4,q:"引当金の貸借対照表上の表示区分に関する記述として、正しいものはどれか。",c:["賞与引当金は流動負債、退職給付引当金は固定負債に表示する。","賞与引当金は固定負債、退職給付引当金は流動負債に表示する。","賞与引当金も退職給付引当金も、資産から控除する形式で表示する。","賞与引当金も退職給付引当金も、純資産の部に表示する。","製品保証引当金は固定負債、特別修繕引当金は流動負債に表示する。"],a:0,e:"負債性引当金は一年基準で区分する。1年内に取り崩す賞与引当金・製品保証引当金は流動負債、退職給付引当金・特別修繕引当金は固定負債。"},
{d:4,q:"偶発債務に関する記述として、正しいものはどれか。",c:["債務保証や手形の割引・裏書譲渡のように、将来債務となる可能性はあるが発生の可能性が高くないものは、引当金を計上せず注記する。","偶発債務は、発生の可能性にかかわらず必ず引当金として計上する。","偶発債務は、貸借対照表にも注記にも表示しない。","偶発債務は、純資産の部から控除して表示する。","債務保証は、保証した時点で保証額の全額を借入金として計上する。"],a:0,e:"偶発債務は引当金の要件（発生の可能性が高い）を満たさないので注記にとどめる。発生の可能性が高くなれば債務保証損失引当金などを計上する。B/Sに載らない隠れ負債なので、銀行員は注記で保証先と金額を必ず確認する。"},
{d:4,q:"退職給付債務の説明として、正しいものはどれか。",c:["将来支払う退職給付のうち、当期末までに発生していると認められる部分を割引率で現在価値に割り引いたもの","将来支払う退職給付の総額を割り引かずに合計したもの","当期に実際に支払った退職金の合計額","年金資産の期末時価","過去に積み立てた退職給付引当金の累計額"],a:0,e:"退職給付債務は当期末までに発生した退職給付の見込額の割引現在価値。個別B/Sではこれから年金資産を控除（未認識項目を調整）した額を退職給付引当金として固定負債に計上する。"},
{d:4,q:"退職給付費用の計算式として、正しいものはどれか。",c:["勤務費用 ＋ 利息費用 − 期待運用収益（± 数理計算上の差異等の費用処理額）","勤務費用 − 利息費用 ＋ 期待運用収益","当期に支払った退職一時金 ＋ 年金掛金","退職給付債務 − 年金資産","退職給付債務 × 割引率"],a:0,e:"退職給付費用は勤務費用（当期の勤務で増えた債務）と利息費用（時の経過で増えた債務）から期待運用収益（年金資産の運用益）を引く。年金運用がうまくいけば費用は減る。退職給付債務−年金資産は引当金の残高。"},
{d:4,q:"税効果会計の対象に関する次の記述のうち、正しいものを1つ選びなさい。",c:["交際費の損金不算入額は永久差異であり、税効果会計の対象とならない。","交際費の損金不算入額は一時差異であり、繰延税金資産を計上する。","税効果会計は、永久差異のみを対象とする。","受取配当金の益金不算入額は一時差異であり、繰延税金負債を計上する。","税効果会計は、会計上の利益と課税所得のすべての差異について繰延税金資産・負債を計上する。"],a:0,e:"税効果会計の対象は将来解消する一時差異のみ。交際費・寄付金の損金不算入、受取配当金の益金不算入、罰科金などは永久に解消しない永久差異で対象外。"},
{d:4,q:"将来減算一時差異が生じた場合の会計処理として、正しいものはどれか。",c:["一時差異に法定実効税率を乗じた額を繰延税金資産として計上し、法人税等調整額で法人税等を減額する。","一時差異に法定実効税率を乗じた額を繰延税金負債として計上する。","一時差異の全額を繰延税金資産として計上する。","一時差異に法定実効税率を乗じた額を特別利益として計上する。","一時差異が生じても、会計処理は不要である。"],a:0,e:"将来減算一時差異（貸倒引当金の損金不算入、減価償却超過額など）は将来の税金を減らすので繰延税金資産（税金の前払い）を計上する。将来加算一時差異なら繰延税金負債。金額は一時差異×法定実効税率。"},
{d:4,q:"当期末の将来減算一時差異が500千円、法定実効税率が30%である場合に計上する繰延税金資産はいくらか（回収可能性に問題はないものとする）。",c:["150千円","500千円","350千円","50千円","1,500千円"],a:0,e:"繰延税金資産＝将来減算一時差異×法定実効税率＝500×30%＝150千円。一時差異そのもの（500千円）や税引後の350千円を選ばないこと。"},
{d:4,q:"繰延税金資産・繰延税金負債の貸借対照表上の表示として、正しいものはどれか。",c:["繰延税金資産は投資その他の資産、繰延税金負債は固定負債に表示し、同一納税主体のものは相殺して表示する。","繰延税金資産は流動資産、繰延税金負債は流動負債に表示する。","繰延税金資産は繰延資産、繰延税金負債は純資産の部に表示する。","繰延税金資産と繰延税金負債は、相殺せず必ず両建てで表示する。","繰延税金資産は無形固定資産に表示する。"],a:0,e:"現行基準では繰延税金資産は投資その他の資産、繰延税金負債は固定負債にまとめて表示し、流動区分には表示しない。同一納税主体の資産と負債は相殺して純額表示する。"},
{d:4,q:"法人税等調整額に関する記述として、正しいものはどれか。",c:["繰延税金資産が増加した場合、法人税等調整額により当期の法人税等の負担額は減少する。","繰延税金資産が増加した場合、法人税等調整額により当期の法人税等の負担額は増加する。","法人税等調整額は、営業外損益に表示する。","法人税等調整額は、実際に納付する税額を変える。","法人税等調整額は、貸借対照表の純資産の部に直接計上する。"],a:0,e:"税効果会計は税引前利益と税負担を対応させる手続で、繰延税金資産の増加は将来の税金の前払いとして当期の税負担を減らす方向（法人税等調整額の貸方）に働く。納付税額そのものは変わらない。"},
{d:4,q:"株主資本を構成する項目の組み合わせとして、正しいものはどれか。",c:["資本金・資本剰余金・利益剰余金・自己株式","資本金・新株予約権・非支配株主持分","資本金・資本剰余金・その他有価証券評価差額金","資本金・利益剰余金・繰延ヘッジ損益","資本金・資本剰余金・利益剰余金・新株予約権"],a:0,e:"株主資本＝資本金＋資本剰余金＋利益剰余金−自己株式。その他有価証券評価差額金・繰延ヘッジ損益は評価・換算差額等、新株予約権・非支配株主持分は株主資本の外。"},
{d:4,q:"株式の払込金額のうち資本金に組み入れない額の限度として、正しいものはどれか。",c:["払込金額の2分の1を超えない額を資本金とせず、資本準備金とすることができる。","払込金額の4分の1を超えない額を資本準備金とすることができる。","払込金額の全額を資本準備金とすることができる。","払込金額の3分の1を超えない額を利益準備金とすることができる。","払込金額は必ず全額を資本金としなければならない。"],a:0,e:"会社法では払込金額の全額を資本金とするのが原則だが、2分の1を超えない額は資本金とせず資本準備金にできる。「4分の1」は準備金の積立限度（資本金の4分の1）で、数字の入替がひっかけ。"},
{d:4,q:"資本金10,000千円、資本準備金1,500千円、利益準備金900千円の会社が、その他利益剰余金を原資として600千円の剰余金の配当を行う。積み立てるべき利益準備金の額はいくらか。",c:["60千円","100千円","600千円","150千円","0円"],a:0,e:"配当額の10分の1（600×1/10＝60千円）を、準備金合計が資本金の4分の1（10,000×1/4＝2,500千円）に達するまで積み立てる。現在の準備金合計は2,400千円で余裕は100千円なので、小さい方の60千円を積み立てる。"},
{d:4,q:"自己株式の貸借対照表上の取り扱いとして、正しいものはどれか。",c:["取得原価で株主資本の末尾に控除（マイナス）表示する。","投資有価証券として投資その他の資産に計上する。","流動資産の有価証券に含めて表示する。","固定負債に計上する。","時価で評価し、評価差額を営業外損益に計上する。"],a:0,e:"自己株式は株主への払戻しの性格を持つため、資産ではなく株主資本の控除項目として表示する。「資産計上する」が定番の誤り。"},
{d:4,q:"自己株式を帳簿価額を上回る価額で処分した場合の差額（処分差益）の処理として、正しいものはどれか。",c:["その他資本剰余金に計上する。","特別利益に計上する。","営業外収益に計上する。","繰越利益剰余金に計上する。","資本金に計上する。"],a:0,e:"自己株式の処分は株主との資本取引なので、差益は損益ではなくその他資本剰余金に計上する。差損もその他資本剰余金から減額し、不足分は繰越利益剰余金から減額する。P/Lには出ない。"},
{d:4,q:"財務分析で用いる自己資本の範囲として、正しいものはどれか。",c:["純資産の部の合計から新株予約権と非支配株主持分を除いたもの（株主資本＋評価・換算差額等）","純資産の部の合計そのもの","資本金と資本準備金の合計","株主資本から利益剰余金を除いたもの","資産合計から流動負債を除いたもの"],a:0,e:"自己資本＝純資産−新株予約権−非支配株主持分。新株予約権は行使されるまで株主のものではなく、非支配株主持分は親会社株主の持分ではないため除く。"},
{d:4,q:"個別貸借対照表の「評価・換算差額等」に含まれる項目として、正しいものはどれか。",c:["その他有価証券評価差額金","利益準備金","自己株式","新株予約権","資本準備金"],a:0,e:"評価・換算差額等はその他有価証券評価差額金・繰延ヘッジ損益・土地再評価差額金など、資産の評価替えで生じ損益を通さず純資産に直入した項目。利益準備金・資本準備金・自己株式は株主資本、新株予約権は独立の区分。"},
{d:4,q:"純資産の部に関する次の記述のうち、正しいものを1つ選びなさい。",c:["新株予約権は純資産の部に表示されるが、株主資本には含まれない。","新株予約権は固定負債に表示する。","非支配株主持分は、個別貸借対照表の株主資本に含まれる。","純資産の合計がマイナスの状態を債務超過といい、資産が負債を上回っている。","剰余金の配当は、純資産の額にかかわらず自由に行うことができる。"],a:0,e:"新株予約権は純資産の部に独立して表示し、株主資本には入らない。非支配株主持分は連結B/Sのみ。債務超過は負債が資産を上回る状態。配当は分配可能額の範囲内で、純資産300万円未満の会社は配当できない。"},

/* ===== Set 5: 損益計算書 ===== */
{d:5,q:"損益計算書に表示される5つの利益を上から順に並べたものとして、正しいものはどれか。",c:["売上総利益→営業利益→経常利益→税引前当期純利益→当期純利益","営業利益→売上総利益→経常利益→税引前当期純利益→当期純利益","売上総利益→経常利益→営業利益→税引前当期純利益→当期純利益","売上総利益→営業利益→税引前当期純利益→経常利益→当期純利益","経常利益→営業利益→売上総利益→税引前当期純利益→当期純利益"],a:0,e:"P/Lは売上高から売上原価→販管費→営業外損益→特別損益→法人税等の順に差し引き、売上総利益・営業利益・経常利益・税引前当期純利益・当期純利益を段階的に表示する。"},
{d:5,q:"営業利益の計算式として、正しいものはどれか。",c:["売上総利益 − 販売費及び一般管理費","売上高 − 売上原価","経常利益 − 営業外収益 ＋ 営業外費用 ＋ 特別損失","売上高 − 売上原価 − 支払利息","税引前当期純利益 − 法人税等"],a:0,e:"営業利益＝売上総利益−販管費で、本業のもうけを表す。売上高−売上原価は売上総利益。支払利息は営業外費用なので営業利益には影響しない。"},
{d:5,q:"経常利益の計算に含まれない項目として、正しいものはどれか。",c:["固定資産売却益","受取利息","支払利息","受取配当金","有価証券売却損"],a:0,e:"経常利益＝営業利益＋営業外収益−営業外費用。固定資産売却益は臨時の特別利益で、経常利益の後に加算される。利息・配当・有価証券売却損益は営業外項目。"},
{d:5,q:"支払利息の損益計算書上の表示区分として、正しいものはどれか。",c:["営業外費用","販売費及び一般管理費","売上原価","特別損失","法人税等"],a:0,e:"支払利息は財務活動から経常的に生じる費用なので営業外費用。営業利益には影響せず経常利益を減らす。借入依存度の高い会社は営業利益と経常利益の差が大きくなる。"},
{d:5,q:"収益認識に関する会計基準の5つのステップに関する次の記述のうち、誤っているものを1つ選びなさい。",c:["収益は、顧客から現金を受け取った時点で認識する。","第1ステップでは、顧客との契約を識別する。","第2ステップでは、契約における履行義務を識別する。","第3ステップでは取引価格を算定し、第4ステップでそれを各履行義務に配分する。","第5ステップでは、履行義務を充足した時に、または充足するにつれて収益を認識する。"],a:0,e:"収益は現金の受取時ではなく、財・サービスの支配が顧客に移転して履行義務を充足した時に認識する。現金受取時に認識するのは現金主義。"},
{d:5,q:"一定の期間にわたり収益を認識する取引の例として、正しいものはどれか。",c:["長期の工事契約について、進捗度に応じて収益を認識する場合","店舗での商品の販売","出荷基準による製品の販売","土地の売却","有価証券の売却"],a:0,e:"工事契約や長期の役務提供は履行義務が一定の期間にわたり充足されるので、進捗度（原価比例法など）に応じて収益を認識する（従来の工事進行基準に相当）。商品・土地の販売は一時点で認識する。"},
{d:5,q:"変動対価に関する記述として、正しいものはどれか。",c:["値引・リベート・返品などにより対価が変動する場合は、変動対価の見積額を控除して収益を計上し、返品見込み分は返金負債として負債に計上する。","値引・リベートは見積らず、実際に発生した期の営業外費用として処理する。","返品見込み分は、返品調整引当金として計上する。","変動対価は考慮せず、常に契約書の金額の全額を売上高とする。","リベートの見込額は、販売費及び一般管理費に計上する。"],a:0,e:"収益認識基準では変動対価を見積って取引価格から控除する。返品見込みは返金負債（負債）として計上し、従来の返品調整引当金は廃止された。"},
{d:5,q:"売上割引（掛代金の期日前回収に伴う代金の一部免除）の現行の会計処理として、正しいものはどれか。",c:["売上高から控除する。","営業外費用に計上する。","販売費及び一般管理費に計上する。","特別損失に計上する。","売上原価に加算する。"],a:0,e:"収益認識基準の下では売上割引は変動対価として売上高から控除する。従来は営業外費用だったため、古い知識のままだと誤る。売上値引・戻り・割戻も売上高から控除。"},
{d:5,q:"仕入割引（買掛金の期日前支払に伴う代金の一部免除）の会計処理として、正しいものはどれか。",c:["営業外収益に計上する。","仕入高から控除する。","売上高に加算する。","販売費及び一般管理費から控除する。","特別利益に計上する。"],a:0,e:"買手側の仕入割引は金融上の利益として営業外収益に計上する。仕入値引・仕入戻し・仕入割戻は仕入高から控除するが、仕入割引は控除しない。売上割引（売上高から控除）と非対称な点がひっかけ。"},
{d:5,q:"他社の商品を仲介して販売する代理人としての取引における売上高の計上方法として、正しいものはどれか。",c:["受け取る手数料の純額を売上高として計上する。","顧客から受け取る対価の総額を売上高として計上する。","顧客から受け取る対価の総額を営業外収益として計上する。","売上高を計上せず、手数料を特別利益とする。","顧客から受け取る対価の総額を売上高、商品の仕入額を販売費及び一般管理費とする。"],a:0,e:"代理人は財・サービスの支配を得ていないので手数料の純額を収益とする。本人なら総額。代理人取引を総額計上すると売上高が水増しされるため、収益認識基準で明確化された。"},
{d:5,q:"商品売買業の当期の資料は、期首商品棚卸高450千円、総仕入高3,300千円、仕入値引100千円、期末商品棚卸高520千円である。当期の売上原価はいくらか。",c:["3,130千円","3,230千円","3,270千円","3,030千円","3,370千円"],a:0,e:"純仕入高＝3,300−100＝3,200千円。売上原価＝期首450＋純仕入3,200−期末520＝3,130千円。仕入値引を控除し忘れると3,230千円、期末の符号を間違えると4,170千円などになる。"},
{d:5,q:"製造業の当期の資料は、材料費1,200千円、労務費800千円、経費500千円、期首仕掛品300千円、期末仕掛品400千円である。当期製品製造原価はいくらか。",c:["2,400千円","2,500千円","2,600千円","2,200千円","2,900千円"],a:0,e:"当期総製造費用＝1,200＋800＋500＝2,500千円。当期製品製造原価＝2,500＋期首仕掛品300−期末仕掛品400＝2,400千円。仕掛品の増減を加減し忘れると2,500千円になる。"},
{d:5,q:"製造業の当期の資料は、期首製品棚卸高600千円、当期製品製造原価4,000千円、期末製品棚卸高700千円である。当期の売上原価はいくらか。",c:["3,900千円","4,100千円","4,000千円","3,300千円","4,700千円"],a:0,e:"製造業の売上原価＝期首製品＋当期製品製造原価−期末製品＝600＋4,000−700＝3,900千円。商業の「期首商品＋当期仕入−期末商品」の仕入を当期製品製造原価に置き換えた形。"},
{d:5,q:"販売費及び一般管理費に計上される項目として、正しいものはどれか。",c:["売上債権に対する貸倒引当金繰入額","支払利息","固定資産除却損","貸付金に対する貸倒引当金繰入額","減損損失"],a:0,e:"売上債権に対する貸倒引当金繰入は営業活動の費用なので販管費。貸付金分は営業外費用、支払利息は営業外費用、固定資産除却損・減損損失は特別損失。"},
{d:5,q:"営業外収益に計上される項目として、正しいものはどれか。",c:["受取配当金","固定資産売却益","負ののれん発生益","売上高","債務免除益"],a:0,e:"受取利息・受取配当金・有価証券利息・仕入割引・為替差益などは営業外収益。固定資産売却益・負ののれん発生益・債務免除益は特別利益。"},
{d:5,q:"特別損失に計上される項目として、正しいものはどれか。",c:["減損損失","減価償却費","手形売却損","売買目的有価証券の評価損","貸倒引当金繰入額"],a:0,e:"減損損失は臨時・巨額の損失なので特別損失。減価償却費は販管費または製造原価、手形売却損・売買目的有価証券評価損は営業外費用、貸倒引当金繰入は販管費（営業外費用）。"},
{d:5,q:"減価償却費と減損損失の損益計算書上の表示区分の組み合わせとして、正しいものはどれか。",c:["減価償却費＝販売費及び一般管理費（または製造原価）、減損損失＝特別損失","減価償却費＝特別損失、減損損失＝販売費及び一般管理費","減価償却費＝営業外費用、減損損失＝営業外費用","減価償却費＝販売費及び一般管理費、減損損失＝営業外費用","減価償却費＝売上高からの控除、減損損失＝特別損失"],a:0,e:"減価償却は毎期規則的に行う費用配分なので営業費用（販管費・製造原価）、減損は臨時の切下げなので特別損失。同じ固定資産に関する費用でも経常的か臨時かで段が変わる。"},
{d:5,q:"有価証券の評価損の表示区分に関する記述として、正しいものはどれか。",c:["売買目的有価証券の評価損は営業外費用、その他有価証券の減損処理（強制評価減）による評価損は特別損失に計上する。","売買目的有価証券の評価損は特別損失、その他有価証券の減損処理による評価損は営業外費用に計上する。","有価証券の評価損はすべて販売費及び一般管理費に計上する。","有価証券の評価損はすべて純資産の部に直接計上する。","売買目的有価証券の評価損は売上原価に計上する。"],a:0,e:"売買目的有価証券の時価変動は経常的な営業外損益。時価の著しい下落による減損処理は臨時の損失なので特別損失。その他有価証券の通常の評価差額（純資産直入）と減損（P/L）を区別する。"},
{d:5,q:"受取手形を期日前に銀行で割り引いた際の手形売却損の表示区分として、正しいものはどれか。",c:["営業外費用","売上原価","販売費及び一般管理費","特別損失","売上高からの控除"],a:0,e:"手形の割引は資金調達の一種なので、割引料（手形売却損）は支払利息と同じ営業外費用。販管費の支払手数料と混同しない。"},
{d:5,q:"損益計算書における法人税等調整額の表示位置として、正しいものはどれか。",c:["「法人税、住民税及び事業税」の次に表示し、これを加減して当期純利益を計算する。","営業外費用の区分に表示する。","特別損失の区分に表示する。","販売費及び一般管理費の区分に表示する。","売上原価の区分に表示する。"],a:0,e:"法人税等調整額は税効果会計の調整項目で、税引前当期純利益から法人税、住民税及び事業税を差し引いた後に加減して当期純利益を求める。"},
{d:5,q:"事業税のうち外形標準課税（付加価値割・資本割）の損益計算書上の表示として、正しいものはどれか。",c:["販売費及び一般管理費（租税公課）に表示する。","「法人税、住民税及び事業税」に含めて表示する。","営業外費用に表示する。","特別損失に表示する。","法人税等調整額に含めて表示する。"],a:0,e:"外形標準課税は利益ではなく付加価値や資本金を課税標準とするため、利益に対する税金ではなく販管費（租税公課）として表示する。所得割は法人税等に含める。"},
{d:5,q:"1株当たり当期純利益（EPS）の計算式として、正しいものはどれか。",c:["当期純利益（連結では親会社株主に帰属する当期純利益）÷ 期中平均発行済株式数（自己株式を除く）","当期純利益 ÷ 期末発行済株式数（自己株式を含む）","経常利益 ÷ 期中平均発行済株式数","当期純利益 ÷ 純資産","株価 ÷ 当期純利益"],a:0,e:"EPSの分母は自己株式を除いた期中平均株式数、分子は普通株主に帰属する当期純利益。株価÷EPSはPER（株価収益率）。"},
{d:5,q:"包括利益に関する記述として、正しいものはどれか。",c:["包括利益は当期純利益にその他の包括利益を加えたもので、連結財務諸表で表示され、個別財務諸表では表示を要しない。","包括利益は、個別財務諸表でのみ表示される。","包括利益は、当期純利益から配当金を差し引いたものである。","その他の包括利益には、受取利息や支払利息が含まれる。","包括利益は、経常利益に特別損益を加減したものである。"],a:0,e:"包括利益＝当期純利益＋その他の包括利益（その他有価証券評価差額金の増減、為替換算調整勘定の増減、退職給付に係る調整額など）。連結財務諸表で表示し、個別では当面表示不要。"},
{d:5,q:"損益計算書の表示原則に関する次の記述のうち、正しいものを1つ選びなさい。",c:["費用と収益は総額で表示し、受取利息と支払利息を相殺して純額で表示することは認められない。","受取利息と支払利息は、相殺して純額で表示しなければならない。","売上高は売上原価を控除した純額で表示する。","損益計算書は、営業損益計算・経常損益計算の2区分のみで構成される。","特別損益は営業損益計算の区分に表示する。"],a:0,e:"総額主義により費用・収益は相殺しない。P/Lは営業損益計算・経常損益計算・純損益計算の3区分で、特別損益は純損益計算の区分。"},
{d:5,q:"連結損益計算書における当期純利益の表示に関する記述として、正しいものはどれか。",c:["当期純利益から非支配株主に帰属する当期純利益を控除して、親会社株主に帰属する当期純利益を表示する。","当期純利益に非支配株主に帰属する当期純利益を加算して、親会社株主に帰属する当期純利益を表示する。","非支配株主に帰属する当期純利益は、営業外費用に表示する。","連結損益計算書には、親会社株主に帰属する当期純利益は表示しない。","非支配株主に帰属する当期純利益は、特別損失に表示する。"],a:0,e:"連結P/Lでは当期純利益を親会社株主分と非支配株主分に分けて表示する。ROE・EPSの分子は親会社株主に帰属する当期純利益。"},

/* ===== Set 6: キャッシュ・フロー計算書と連結・注記 ===== */
{d:6,q:"キャッシュ・フロー計算書において、営業活動によるキャッシュ・フローの区分に表示される項目として、正しいものはどれか。",c:["法人税等の支払額","有形固定資産の取得による支出","借入金の返済による支出","配当金の支払額","自己株式の取得による支出"],a:0,e:"法人税等の支払は営業活動の区分（小計の下）に表示する。固定資産の取得は投資活動、借入金の返済・配当金の支払・自己株式の取得は財務活動。"},
{d:6,q:"投資活動によるキャッシュ・フローの区分に表示される項目として、正しいものはどれか。",c:["投資有価証券の取得による支出","社債の発行による収入","商品の仕入による支出","株式の発行による収入","人件費の支出"],a:0,e:"投資活動は固定資産・有価証券（売買目的以外）の取得売却、貸付けと回収など。社債・株式の発行は財務活動、仕入・人件費の支出は営業活動。"},
{d:6,q:"財務活動によるキャッシュ・フローの区分に表示される項目として、正しいものはどれか。",c:["配当金の支払額","利息の受取額","貸付金の回収による収入","固定資産の売却による収入","災害に伴う保険金の受取額"],a:0,e:"配当金の支払は必ず財務活動。利息の受取は営業活動（または投資活動）、貸付金の回収・固定資産売却は投資活動、災害保険金の受取は営業活動。"},
{d:6,q:"キャッシュ・フロー計算書の「現金及び現金同等物」に関する記述として、正しいものはどれか。",c:["現金同等物は、容易に換金可能で価値変動リスクが僅少な短期投資であり、取得日から満期まで3か月以内の定期預金などが該当する。","現金同等物には、上場株式が含まれる。","現金同等物には、満期まで1年以内の定期預金がすべて含まれる。","現金同等物には、売買目的有価証券がすべて含まれる。","現金には、要求払預金（当座預金・普通預金）は含まれない。"],a:0,e:"現金同等物は取得日から満期3か月以内の定期預金・CP・公社債投信など。株式は価値変動リスクが大きいので含まない。要求払預金は現金に含まれる。"},
{d:6,q:"キャッシュ・フロー計算書における利息・配当金の表示に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["支払配当金は、営業活動によるキャッシュ・フローの区分に表示することができる。","受取利息・受取配当金・支払利息を営業活動の区分に表示する方法が認められている。","受取利息・受取配当金を投資活動の区分、支払利息を財務活動の区分に表示する方法が認められている。","支払配当金は、財務活動によるキャッシュ・フローの区分に表示する。","利息・配当金の表示方法は、継続して適用しなければならない。"],a:0,e:"利息と受取配当金は2つの表示方法から選択できるが、支払配当金は財務活動に固定。営業活動に表示できるとする選択肢が誤り。"},
{d:6,q:"間接法による営業活動によるキャッシュ・フローの計算の出発点として、正しいものはどれか。",c:["税引前当期純利益","売上高","営業利益","当期純利益","経常利益"],a:0,e:"日本基準の間接法は税引前当期純利益から出発し、非資金項目・営業外損益・営業資産負債の増減を調整して小計を出す。法人税等の支払額は小計の下で別途表示する。"},
{d:6,q:"間接法において減価償却費を税引前当期純利益に加算する理由として、正しいものはどれか。",c:["減価償却費は現金の支出を伴わない費用であるため","減価償却費は現金の収入を伴う収益であるため","減価償却費は投資活動によるキャッシュ・フローに表示するため","減価償却費は税務上損金にならないため","減価償却費は特別損失に表示されるため"],a:0,e:"減価償却費は利益計算では引かれているが現金は出ていないので、現金ベースに戻すために足し戻す。減損損失・のれん償却額・引当金の増加も同じ理由で加算する。"},
{d:6,q:"間接法において、売上債権が期中に増加した場合の調整として、正しいものはどれか。",c:["増加額を税引前当期純利益から減算する。","増加額を税引前当期純利益に加算する。","調整は不要である。","増加額を投資活動によるキャッシュ・フローに表示する。","増加額を財務活動によるキャッシュ・フローに表示する。"],a:0,e:"売上債権の増加は売上が計上されたのに現金が未回収である分なので減算する。資産の増加は減算、負債の増加は加算が原則。"},
{d:6,q:"間接法において、仕入債務が期中に増加した場合の調整として、正しいものはどれか。",c:["増加額を税引前当期純利益に加算する。","増加額を税引前当期純利益から減算する。","調整は不要である。","増加額を財務活動によるキャッシュ・フローに表示する。","増加額を投資活動によるキャッシュ・フローに表示する。"],a:0,e:"仕入債務の増加は仕入（費用）を計上したのに現金を払っていない分なので加算する。棚卸資産の増加は現金が在庫に化けているので減算。"},
{d:6,q:"当期の資料は、税引前当期純利益800千円、減価償却費200千円、売上債権の増加額150千円、棚卸資産の増加額50千円、仕入債務の増加額100千円、法人税等の支払額300千円である（利息・配当はない）。間接法による営業活動によるキャッシュ・フローはいくらか。",c:["600千円","900千円","700千円","500千円","1,100千円"],a:0,e:"小計＝800＋200−150−50＋100＝900千円。法人税等の支払額300千円を差し引いて営業CF＝600千円。小計（900千円）で止めるのが典型的な誤り。"},
{d:6,q:"営業活動によるキャッシュ・フローが500千円、投資活動によるキャッシュ・フローが△300千円、財務活動によるキャッシュ・フローが△150千円である場合、フリー・キャッシュ・フロー（営業CF＋投資CF）はいくらか。",c:["200千円","50千円","800千円","350千円","△100千円"],a:0,e:"フリー・キャッシュ・フロー＝営業CF＋投資CF＝500＋（△300）＝200千円。財務CFは含めない（財務CFまで引くと50千円で現金の増減額になる）。"},
{d:6,q:"直接法と間接法に関する記述として、正しいものはどれか。",c:["営業収入や仕入支出を総額で表示するのが直接法で、どちらの方法でも小計以降（利息・配当金の受取額、利息の支払額、法人税等の支払額）の表示は同じである。","間接法では営業収入や仕入支出を総額で表示する。","直接法と間接法では、営業活動によるキャッシュ・フローの合計額が異なる。","直接法は投資活動の区分、間接法は財務活動の区分の作成方法である。","間接法では、営業活動によるキャッシュ・フローは売上高から出発して計算する。"],a:0,e:"直接法は主要な取引ごとに総額表示、間接法は税引前当期純利益からの調整で、小計までの表示方法が違うだけで営業CFの合計は同じ。実務では間接法が大半。"},
{d:6,q:"営業活動によるキャッシュ・フローがマイナスで、財務活動によるキャッシュ・フローがプラスの会社の状態の読み方として、正しいものはどれか。",c:["本業で現金が生み出せず、借入などの資金調達で不足を穴埋めしている状態であり、資金繰りに注意が必要である。","本業で潤沢に現金を生み、借入金を順調に返済している健全な状態である。","設備投資を積極的に行い、その資金を本業の現金で賄っている状態である。","営業活動がマイナスでも財務活動がプラスなら、資金繰りの問題は生じない。","利益が出ていれば営業活動によるキャッシュ・フローは必ずプラスになるので、この組み合わせは起こらない。"],a:0,e:"営業CFマイナス・財務CFプラスは借入依存のサイン。利益が出ていても売上債権や在庫が膨らめば営業CFはマイナスになり得る（粉飾の兆候でもある）。健全な成熟企業は営業CF＋・投資CF−・財務CF−。"},
{d:6,q:"連結の範囲の決定に関する記述として、正しいものはどれか。",c:["議決権の過半数を所有していなくても、40%以上50%以下を所有し役員派遣や契約などにより意思決定機関を実質的に支配していれば子会社となる（支配力基準）。","議決権の過半数を所有している会社のみが子会社となり、それ以外は子会社にならない（持株基準）。","議決権の20%以上を所有していれば、すべて子会社として連結する。","子会社であっても、親会社の判断で任意に連結の範囲から除外できる。","海外に所在する子会社は、連結の範囲に含めない。"],a:0,e:"連結の範囲は持株比率だけでなく実質的な支配で判定する支配力基準。原則としてすべての子会社（海外子会社を含む）を連結し、除外は重要性の乏しい場合などに限られる。"},
{d:6,q:"議決権の40%以上50%以下を所有する会社が子会社と判定される場合の要件の例として、正しいものはどれか。",c:["自己と緊密な者の議決権を合わせて過半数となる、または役員の過半数を派遣しているなど、意思決定機関を支配している事実がある場合","その会社の売上高が親会社の売上高を上回っている場合","その会社が親会社と同じ業種である場合","その会社の株式に市場価格がある場合","その会社が親会社と同じ決算日を採用している場合"],a:0,e:"40%以上50%以下でも、緊密な者と合わせて過半数、役員の過半数派遣、重要な財務・営業方針を決定する契約などがあれば子会社。業種や決算日は関係ない。"},
{d:6,q:"関連会社と持分法に関する記述として、正しいものはどれか。",c:["議決権の20%以上を所有し財務・営業方針に重要な影響を与えることができる会社は関連会社とし、持分法を適用する。","議決権の20%以上を所有する会社は、すべて子会社として連結する。","関連会社の資産・負債・収益・費用は、連結財務諸表に全額合算する。","持分法は、議決権の50%超を所有する会社にのみ適用する。","関連会社に対する投資は、連結財務諸表上も取得原価のまま据え置く。"],a:0,e:"関連会社は影響力基準（20%以上、または15%以上20%未満で一定要件）で判定し、資産・負債は合算せず投資勘定のみを持分に応じて増減させる持分法（一行連結）を適用する。"},
{d:6,q:"持分法による投資損益の連結損益計算書上の表示区分として、正しいものはどれか。",c:["営業外損益","売上高","販売費及び一般管理費","特別損益","法人税等調整額"],a:0,e:"持分法による投資利益・投資損失は営業外損益に表示する。関連会社の利益のうち持分相当額が投資勘定の増加と営業外収益として反映される。"},
{d:6,q:"連結財務諸表の作成手続に関する次の記述のうち、正しいものを1つ選びなさい。",c:["親会社の子会社に対する投資と子会社の資本を相殺消去し、投資額が子会社の資本の親会社持分を超える額をのれんとして計上する。","親会社の投資と子会社の資本は相殺せず、両方をそのまま連結貸借対照表に表示する。","親子会社間の売掛金と買掛金は、相殺せず両建てで表示する。","子会社の決算日が親会社と異なる場合、その差が6か月以内であれば子会社の決算をそのまま使用できる。","親子会社間の取引で生じた棚卸資産の未実現利益は、消去しない。"],a:0,e:"連結では投資と資本の相殺消去（資本連結）、債権債務・取引高の相殺消去、未実現利益の消去を行う。決算日の差は3か月以内なら子会社の決算をそのまま使える。"},
{d:6,q:"連結上ののれんと負ののれんの処理に関する記述として、正しいものはどれか。",c:["のれんは20年以内で規則的に償却し償却額は販売費及び一般管理費に、負ののれんは発生した期の特別利益に計上する。","のれんは償却せず、負ののれんは20年以内で償却する。","のれんも負ののれんも、発生した期の特別損益として一括処理する。","のれんは5年以内で償却し、負ののれんは固定負債に計上する。","のれんは純資産の部に、負ののれんは資産の部に計上する。"],a:0,e:"のれんは無形固定資産として20年以内で償却（販管費）、負ののれんは発生時に特別利益。IFRSのように非償却とするのは日本基準では誤り。"},
{d:6,q:"非支配株主持分の連結貸借対照表上の表示区分として、正しいものはどれか。",c:["純資産の部（株主資本の外）","固定負債","流動負債","株主資本の内訳","投資その他の資産"],a:0,e:"非支配株主持分は子会社の純資産のうち親会社以外の株主に帰属する部分で、連結B/Sの純資産の部に株主資本とは別に表示する。負債ではなく、個別B/Sには登場しない。"},
{d:6,q:"親会社が子会社に商品を販売し、期末に子会社がその商品を在庫として保有している場合の連結上の処理として、正しいものはどれか。",c:["親会社の売上高と子会社の仕入高を相殺消去し、期末在庫に含まれる未実現利益を消去する。","親会社の売上高はそのまま計上し、子会社の仕入高のみを消去する。","期末在庫に含まれる未実現利益は、連結上も利益として計上する。","親会社の売上高と子会社の仕入高は相殺せず、未実現利益のみを消去する。","グループ内の取引であっても、連結上何も消去しない。"],a:0,e:"グループ内の取引は連結上は内部取引なので売上高と仕入高を相殺し、外部に売れていない在庫に含まれる利益（未実現利益）も消去する。子会社への押込み販売による利益操作はここで消える。"},
{d:6,q:"親会社と子会社の決算日が異なる場合の取り扱いとして、正しいものはどれか。",c:["決算日の差異が3か月を超えない場合は、子会社の正規の決算を基礎として連結できる。","決算日の差異にかかわらず、常に子会社の正規の決算をそのまま使用できる。","決算日の差異が6か月を超えない場合は、子会社の正規の決算を基礎として連結できる。","決算日が異なる子会社は、連結の範囲から除外する。","決算日が異なる場合、必ず子会社の決算日を親会社に合わせて変更しなければならない。"],a:0,e:"決算日の差異が3か月以内なら子会社の正規の決算を使用できる（重要な不一致は調整）。3か月超なら親会社の決算日に合わせた仮決算が必要。数字を6か月にした選択肢が誤り。"},
{d:6,q:"後発事象に関する記述として、正しいものはどれか。",c:["決算日後に主要な得意先が倒産し、決算日時点で既に回収不能の状況にあったことが判明した場合は修正後発事象として財務諸表を修正し、決算日後の火災による損害は開示後発事象として注記する。","決算日後に生じた事象は、すべて財務諸表を修正して反映させる。","決算日後に生じた事象は、財務諸表に一切反映も注記もしない。","決算日後の火災による損害は、修正後発事象として当期の特別損失に計上する。","決算日後に判明した得意先の倒産は、翌期の財務諸表にのみ反映し、当期には注記もしない。"],a:0,e:"決算日時点で存在した状況の証拠となる事象は修正後発事象（財務諸表を修正）、決算日後に新たに発生した事象は開示後発事象（注記）。事象の発生時点で区別する。"},
{d:6,q:"注記事項・附属明細書に関する次の記述のうち、正しいものを1つ選びなさい。",c:["手形の割引高・裏書譲渡高や債務保証は、偶発債務として注記する。","手形の割引高は、貸借対照表の固定負債に計上する。","会社法の附属明細書には、貸借対照表と損益計算書そのものが含まれる。","会計方針を変更した場合でも、その理由や影響額は注記しなくてよい。","1株当たり当期純利益や1株当たり純資産は、注記の対象とならない。"],a:0,e:"偶発債務はB/Sに載らない隠れ負債なので注記で確認する。附属明細書は固定資産・引当金・販管費の明細など計算書類を補足する書類。会計方針の変更は理由と影響額を注記し、1株当たり情報も注記事項。"},
{d:6,q:"粉飾決算の兆候に関する次の記述のうち、誤っているものを1つ選びなさい。",c:["営業活動によるキャッシュ・フローが当期純利益を大きく上回っている状態は、粉飾の典型的な兆候である。","売上高の増加を上回るペースで売上債権が増加し、売上債権回転期間が長期化している。","売上高が横ばいなのに棚卸資産が急増し、売上原価率が低下している。","修繕費や研究開発費など本来費用とすべき支出が資産に計上されている。","期末月に売上が集中し、翌期首に多額の返品が発生している。"],a:0,e:"減価償却費などの非資金費用があるため、営業CFが当期純利益を上回るのはむしろ健全な状態。粉飾では利益が出ているのに営業CFがマイナスになりやすい。他の4つは架空売上・在庫水増し・費用の資産化・押込み販売の兆候。"}
]);
window.__Q = (window.__Q || []).concat([
/* ===== Set 7: 収益性の分析 ===== */
{d:7,q:"経常利益240百万円、期末の総資本3,000百万円のとき、期末の数値を用いた総資本経常利益率はどれか（小数点以下第2位を四捨五入）。",c:["8.0%","4.0%","12.5%","16.0%","0.8%"],a:0,e:"総資本経常利益率＝経常利益÷総資本×100＝240÷3,000×100＝8.0%。総資本は負債＋純資産（＝総資産）で、負債と純資産を二重に足して6,000で割ると4.0%、逆数にすると12.5倍という誤答になる。"},
{d:7,q:"経常利益300百万円、総資本が期首2,400百万円・期末2,600百万円のとき、期首・期末平均の総資本を用いた総資本経常利益率はどれか（小数点以下第2位を四捨五入）。",c:["12.0%","11.5%","12.5%","6.0%","24.0%"],a:0,e:"平均総資本＝（2,400＋2,600）÷2＝2,500。総資本経常利益率＝300÷2,500×100＝12.0%。期末で割ると11.5%、期首で割ると12.5%、期首＋期末の合計で割ると6.0%になる。分母は平均が原則だが、問題の指示に従う。"},
{d:7,q:"売上高8,000百万円、営業利益520百万円、営業外収益40百万円、営業外費用80百万円のとき、売上高経常利益率はどれか（小数点以下第2位を四捨五入）。",c:["6.0%","6.5%","5.5%","7.0%","0.6%"],a:0,e:"経常利益＝営業利益＋営業外収益−営業外費用＝520＋40−80＝480。売上高経常利益率＝480÷8,000×100＝6.0%。営業利益をそのまま使うと6.5%（売上高営業利益率）、営業外収益を足し忘れると5.5%。"},
{d:7,q:"売上高9,000百万円、総資本が期首3,600百万円・期末3,900百万円のとき、期首・期末平均の総資本を用いた総資本回転率はどれか（小数点以下第2位を四捨五入）。",c:["2.4回","2.3回","2.5回","0.4回","1.2回"],a:0,e:"平均総資本＝（3,600＋3,900）÷2＝3,750。総資本回転率＝売上高÷総資本＝9,000÷3,750＝2.4回。回転率は×100しない（単位は回）。期末で割ると2.3回、逆数にすると0.4になる。"},
{d:7,q:"売上高経常利益率が4.0%、総資本回転率が1.5回のとき、総資本経常利益率はどれか。",c:["6.0%","2.7%","5.5%","4.0%","0.6%"],a:0,e:"総資本経常利益率＝売上高経常利益率×総資本回転率＝4.0%×1.5回＝6.0%。分子・分母の売上高が約分されて経常利益÷総資本になる。割ってしまうと2.7%、足すと5.5という誤りになる。"},
{d:7,q:"期末の受取手形300百万円、売掛金900百万円、年間売上高7,200百万円のとき、期末の売上債権を用いた売上債権回転期間（月）はどれか（小数点以下第2位を四捨五入）。",c:["2.0か月","1.5か月","0.5か月","6.0か月","2.4か月"],a:0,e:"売上債権＝受取手形＋売掛金＝1,200。月商＝7,200÷12＝600。売上債権回転期間＝1,200÷600＝2.0か月。売掛金だけで計算すると1.5か月、回転率（7,200÷1,200＝6.0回）と混同すると6.0という誤答になる。"},
{d:7,q:"期末の売上債権600百万円、年間売上高7,300百万円、1年を365日として、売上債権回転期間（日）はどれか（小数点以下第2位を四捨五入）。",c:["30.0日","29.6日","36.5日","60.0日","3.0日"],a:0,e:"1日当たり売上高＝7,300÷365＝20。売上債権回転期間＝600÷20＝30.0日。360日で計算すると29.6日になるので、問題文の日数指定を必ず確認する。"},
{d:7,q:"年間売上高6,000百万円、売上債権が期首900百万円・期末1,100百万円のとき、期首・期末平均の売上債権を用いた売上債権回転率はどれか（小数点以下第2位を四捨五入）。",c:["6.0回","5.5回","6.7回","3.0回","0.2回"],a:0,e:"平均売上債権＝（900＋1,100）÷2＝1,000。売上債権回転率＝売上高÷売上債権＝6,000÷1,000＝6.0回。期末で割ると5.5回、期首で割ると6.7回。回転期間（月）は12÷6.0＝2.0か月。"},
{d:7,q:"期末の棚卸資産450百万円、年間売上高5,400百万円、売上原価3,600百万円のとき、売上高を用いて計算した期末の棚卸資産回転期間（月）はどれか（小数点以下第2位を四捨五入）。",c:["1.0か月","1.5か月","12.0か月","0.5か月","2.0か月"],a:0,e:"月商＝5,400÷12＝450。棚卸資産回転期間＝450÷450＝1.0か月。売上原価を用いると450÷（3,600÷12）＝1.5か月になる。どちらで割るかは問題文の指示に従う。12.0は回転率（5,400÷450）で単位が違う。"},
{d:7,q:"年間売上原価4,800百万円、年間売上高6,000百万円、棚卸資産が期首500百万円・期末700百万円のとき、売上原価を用い、期首・期末平均の棚卸資産で計算した棚卸資産回転率はどれか（小数点以下第2位を四捨五入）。",c:["8.0回","10.0回","6.9回","9.6回","1.5回"],a:0,e:"平均棚卸資産＝（500＋700）÷2＝600。棚卸資産回転率＝売上原価÷棚卸資産＝4,800÷600＝8.0回。売上高で割ると10.0回、期末だけで割ると6.9回。問題文が「売上原価を用いる」と指定していることに注意。"},
{d:7,q:"期末の支払手形200百万円、買掛金400百万円、年間売上高4,800百万円のとき、売上高を用いた期末の仕入債務回転期間（月）はどれか（小数点以下第2位を四捨五入）。",c:["1.5か月","1.0か月","0.5か月","8.0か月","1.8か月"],a:0,e:"仕入債務＝支払手形＋買掛金＝600。月商＝4,800÷12＝400。仕入債務回転期間＝600÷400＝1.5か月。買掛金だけだと1.0か月、8.0は回転率（4,800÷600）。仕入高で割る指示があればそれに従う。"},
{d:7,q:"年間売上高9,000百万円、期末の固定資産3,600百万円のとき、期末の数値を用いた固定資産回転率はどれか（小数点以下第2位を四捨五入）。",c:["2.5回","0.4回","2.0回","3.0回","4.8回"],a:0,e:"固定資産回転率＝売上高÷固定資産＝9,000÷3,600＝2.5回。回転率は「売上高÷資産」。逆にすると0.4、回転期間に直すと12÷2.5＝4.8か月で単位が異なる。"},
{d:7,q:"当期純利益180百万円、自己資本が期首1,400百万円・期末1,600百万円のとき、期首・期末平均の自己資本を用いた自己資本当期純利益率（ROE）はどれか（小数点以下第2位を四捨五入）。",c:["12.0%","11.3%","12.9%","6.0%","18.0%"],a:0,e:"平均自己資本＝（1,400＋1,600）÷2＝1,500。ROE＝当期純利益÷自己資本×100＝180÷1,500×100＝12.0%。期末で割ると11.3%、期首で割ると12.9%。ROEの分子は当期純利益、分母は自己資本（総資本ではない）。"},
{d:7,q:"売上高5,000百万円、売上原価3,250百万円のとき、売上高総利益率はどれか（小数点以下第2位を四捨五入）。",c:["35.0%","65.0%","53.8%","30.0%","153.8%"],a:0,e:"売上総利益＝5,000−3,250＝1,750。売上高総利益率＝1,750÷5,000×100＝35.0%。65.0%は売上原価率（100%−35%）。売上総利益を売上原価で割ると53.8%になり誤り。"},
{d:7,q:"総資本5,000百万円（うち建設仮勘定200百万円、投資その他の資産600百万円、繰延資産なし）、営業利益420百万円のとき、経営資本＝総資本−（建設仮勘定＋投資その他の資産＋繰延資産）として、期末の経営資本営業利益率はどれか（小数点以下第2位を四捨五入）。",c:["10.0%","8.4%","8.8%","9.5%","7.0%"],a:0,e:"経営資本＝5,000−（200＋600＋0）＝4,200。経営資本営業利益率＝420÷4,200×100＝10.0%。総資本で割ると8.4%（総資本営業利益率）、建設仮勘定だけ引くと8.8%、投資その他の資産だけ引くと9.5%。本業に投下した資本と営業利益を対応させる指標。"},
{d:7,q:"売上高12,500百万円、販売費及び一般管理費2,250百万円のとき、売上高販管費率はどれか（小数点以下第2位を四捨五入）。",c:["18.0%","82.0%","22.0%","1.8%","5.6%"],a:0,e:"売上高販管費率＝販売費及び一般管理費÷売上高×100＝2,250÷12,500×100＝18.0%。売上高総利益率が30%なら売上高営業利益率は30−18＝12%になる、という関係で使う。5.6は逆数（12,500÷2,250）。"},
{d:7,q:"総資本経常利益率の分解式として正しいものはどれか。",c:["売上高経常利益率 × 総資本回転率","売上高経常利益率 ÷ 総資本回転率","売上高経常利益率 × 自己資本比率","総資本回転率 × 固定資産回転率","売上高総利益率 × 総資本回転期間"],a:0,e:"総資本経常利益率＝経常利益/売上高×売上高/総資本＝売上高経常利益率×総資本回転率。利益率（もうけの厚さ）と回転率（資産の効率）に分けて要因分析する。"},
{d:7,q:"総資本経常利益率の分母である「総資本」の説明として正しいものはどれか。",c:["負債と純資産の合計であり、総資産と同額である","純資産のことであり、負債は含まない","流動資産と固定資産の合計から負債を差し引いたもの","有利子負債と自己資本の合計である","資本金と資本剰余金の合計である"],a:0,e:"総資本＝負債＋純資産＝総資産（B/Sの貸方合計＝借方合計）。他人資本（負債）と自己資本（純資産）の両方を含む。純資産だけを分母にするのは自己資本利益率（ROE）。"},
{d:7,q:"資本利益率や回転率を計算するときの分母（総資本・売上債権など）の取り方について、正しいものはどれか。",c:["期首と期末の平均値を用いるのが原則だが、問題文で期末の数値を用いる指示があればそれに従う","必ず期末の数値を用い、平均値を用いることはない","必ず期首の数値を用いる","分子（利益・売上高）も期首と期末の平均にする","分母には前期末ではなく翌期首の数値を用いる"],a:0,e:"分子はP/Lの期間合計（フロー）、分母はB/Sの時点残高（ストック）なので、対応させるために分母は期首・期末平均が原則。ただし試験問題では「期末の数値を用いる」と指定されることが多く、その指示が優先する。"},
{d:7,q:"取引先の売上債権回転期間が前期より大幅に長期化した場合の解釈として、最も適切なものはどれか。",c:["回収条件の悪化や回収遅延、場合によっては期末の押込み販売や架空売上の可能性を疑う","資金効率が改善しており、望ましい変化である","仕入先への支払を早めたことを意味する","在庫が減少したことを意味する","自己資本比率が上昇したことを意味する"],a:0,e:"売上債権回転期間の長期化＝売上に対して債権残高が膨らんでいる＝回収が遅れている、または不良債権・架空売上の疑い。所要運転資金も増えるため、借入需要の中身を確認する。回収が早くなれば回転期間は短縮する。"},
{d:7,q:"棚卸資産回転期間が長期化した場合の解釈として、最も適切なものはどれか。",c:["在庫の滞留や過剰仕入、不良在庫の発生が疑われ、粉飾であれば架空在庫の可能性もある","販売が好調で在庫が不足していることを示す","売上債権の回収が早まったことを示す","固定資産への投資が過大であることを示す","仕入債務の支払を遅らせていることを示す"],a:0,e:"棚卸資産回転期間＝棚卸資産÷月商。長期化は売上に比べて在庫が膨らんだ状態で、滞留在庫・過剰仕入、あるいは利益をかさ上げする架空在庫の疑い。販売好調で在庫不足なら回転期間は短縮する。"},
{d:7,q:"回転率と回転期間の関係として正しいものはどれか。",c:["回転期間（月）＝ 12 ÷ 回転率（回）","回転期間（月）＝ 回転率（回）× 12","回転期間（月）＝ 回転率（回）÷ 12","回転期間（月）＝ 100 ÷ 回転率（回）","回転期間と回転率は互いに無関係である"],a:0,e:"回転率＝売上高÷資産、回転期間（月）＝資産÷（売上高÷12）＝12÷回転率。回転率6回なら回転期間2.0か月。日数なら365÷回転率。回転率が上がれば回転期間は短くなる。"},
{d:7,q:"経営資本の説明として正しいものはどれか。",c:["総資本から建設仮勘定・投資その他の資産・繰延資産など本業に投下されていない資産を除いたもの","総資本から流動負債を差し引いたもの","純資産から新株予約権を差し引いたもの","有形固定資産と無形固定資産の合計","総資本に有利子負債を加えたもの"],a:0,e:"経営資本は営業活動（本業）に使われている資本。未稼働の建設仮勘定、本業外の投資その他の資産、繰延資産を総資本から除く。営業利益と対応させて経営資本営業利益率を計算する。"},
{d:7,q:"ある会社で総資本営業利益率は前期並みなのに総資本経常利益率が大きく低下した。原因として最も適切なものはどれか。",c:["借入金の増加や金利上昇により支払利息など営業外費用が増加した","売上原価率が上昇した","販売費及び一般管理費が増加した","固定資産売却損など特別損失が発生した","法人税等の負担が増加した"],a:0,e:"営業利益と経常利益の差は営業外損益（支払利息・受取利息など）。営業利益率が変わらず経常利益率だけ落ちたなら、財務活動（金利負担）の悪化が原因。売上原価や販管費の増加は営業利益率も下げる。特別損失や法人税は経常利益より下の段階。"},
{d:7,q:"財務分析の方法に関する記述のうち、正しいものはどれか。",c:["比率分析は規模の異なる企業を比較でき、時系列比較や同業他社比較と組み合わせて評価する","実数分析は金額を用いないため規模の影響を受けない","比率が高ければ他社と比較しなくても常に良好と判断できる","時系列比較は同業他社との比較であり、自社の過去との比較は含まない","比率分析では貸借対照表の数値は使わず損益計算書のみを用いる"],a:0,e:"比率分析は2つの数値の割合で規模の差を打ち消す方法。ただし比率単独で良否は言えず、自社の過去（時系列）や同業他社と比べて評価する。実数分析は金額そのものを見る方法。"},

/* ===== Set 8: 安全性の分析 ===== */
{d:8,q:"流動資産3,600百万円、流動負債2,400百万円のとき、流動比率はどれか（小数点以下第2位を四捨五入）。",c:["150.0%","66.7%","120.0%","1.5%","250.0%"],a:0,e:"流動比率＝流動資産÷流動負債×100＝3,600÷2,400×100＝150.0%。逆にすると66.7%。×100を忘れると1.5。高いほど短期の支払能力が高く、200%が理想とされる。"},
{d:8,q:"現金及び預金500百万円、受取手形300百万円、売掛金700百万円、有価証券100百万円、棚卸資産900百万円、その他の流動資産100百万円、流動負債2,000百万円のとき、当座比率はどれか（小数点以下第2位を四捨五入）。",c:["80.0%","130.0%","85.0%","75.0%","125.0%"],a:0,e:"当座資産＝現金及び預金＋受取手形＋売掛金＋有価証券＝500＋300＋700＋100＝1,600。当座比率＝1,600÷2,000×100＝80.0%。流動資産全体2,600で計算すると130.0%（流動比率）、その他の流動資産を含めると85.0%、有価証券を除くと75.0%。棚卸資産・その他流動資産は当座資産に含めない。"},
{d:8,q:"固定資産2,400百万円、自己資本2,000百万円、総資本4,000百万円のとき、固定比率はどれか（小数点以下第2位を四捨五入）。",c:["120.0%","83.3%","60.0%","80.0%","150.0%"],a:0,e:"固定比率＝固定資産÷自己資本×100＝2,400÷2,000×100＝120.0%。総資本で割ると60.0%、逆数にすると83.3%。100%以下が理想（固定資産を自己資本の範囲で賄えている）。"},
{d:8,q:"固定資産3,000百万円、自己資本2,000百万円、固定負債2,000百万円、流動負債1,000百万円のとき、固定長期適合率はどれか（小数点以下第2位を四捨五入）。",c:["75.0%","150.0%","133.3%","60.0%","100.0%"],a:0,e:"固定長期適合率＝固定資産÷（自己資本＋固定負債）×100＝3,000÷4,000×100＝75.0%。自己資本だけで割ると150.0%（固定比率）、流動負債まで分母に入れると60.0%。分母は「自己資本＋固定負債」の長期資金。"},
{d:8,q:"総資本8,000百万円、負債5,200百万円のとき、自己資本比率はどれか（自己資本＝純資産とみなす。小数点以下第2位を四捨五入）。",c:["35.0%","65.0%","53.8%","185.7%","28.0%"],a:0,e:"自己資本＝総資本−負債＝8,000−5,200＝2,800。自己資本比率＝2,800÷8,000×100＝35.0%。65.0%は負債構成比、185.7%は負債比率（5,200÷2,800）、53.8%は自己資本÷負債。"},
{d:8,q:"負債3,000百万円、自己資本2,400百万円のとき、負債比率はどれか（小数点以下第2位を四捨五入）。",c:["125.0%","80.0%","55.6%","44.4%","225.0%"],a:0,e:"負債比率＝負債÷自己資本×100＝3,000÷2,400×100＝125.0%。逆にすると80.0%、総資本（5,400）で割ると55.6%（負債構成比）、44.4%は自己資本比率。負債比率は低いほど安全で、100%以下が一つの目安。"},
{d:8,q:"総資本10,000百万円、短期借入金600百万円、1年内返済予定の長期借入金200百万円、長期借入金1,400百万円、社債300百万円、買掛金500百万円のとき、有利子負債依存度はどれか（小数点以下第2位を四捨五入）。",c:["25.0%","30.0%","23.0%","22.0%","20.0%"],a:0,e:"有利子負債＝短期借入金＋1年内返済予定の長期借入金＋長期借入金＋社債＝600＋200＋1,400＋300＝2,500。有利子負債依存度＝2,500÷10,000×100＝25.0%。買掛金は利息の付かない負債なので含めない（含めると30.0%）。1年内返済予定分を落とすと23.0%、社債を落とすと22.0%。"},
{d:8,q:"営業利益360百万円、受取利息・受取配当金40百万円、支払利息80百万円のとき、インタレスト・カバレッジ・レシオはどれか（小数点以下第2位を四捨五入）。",c:["5.0倍","4.5倍","0.2倍","4.0倍","5.5倍"],a:0,e:"インタレスト・カバレッジ・レシオ＝（営業利益＋受取利息・受取配当金）÷支払利息＝（360＋40）÷80＝5.0倍。営業利益だけで割ると4.5倍、受取利息を引いてしまうと4.0倍。利息の支払余力を示し、高いほど安全、1倍未満は本業の利益で利息を払えない状態。"},
{d:8,q:"売上債権1,500百万円、棚卸資産900百万円、仕入債務1,200百万円のとき、所要運転資金はどれか。",c:["1,200百万円","3,600百万円","300百万円","1,800百万円","600百万円"],a:0,e:"所要運転資金＝売上債権＋棚卸資産−仕入債務＝1,500＋900−1,200＝1,200百万円。すべて足すと3,600、仕入債務を足し忘れて売上債権−仕入債務にすると300。営業循環の中で会社が立て替えている資金の額。"},
{d:8,q:"前期は売上債権1,200百万円・棚卸資産800百万円・仕入債務1,000百万円、当期は売上債権1,500百万円・棚卸資産900百万円・仕入債務1,200百万円であった。当期の増加運転資金はどれか。",c:["200百万円","1,200百万円","1,000百万円","400百万円","700百万円"],a:0,e:"前期の所要運転資金＝1,200＋800−1,000＝1,000。当期＝1,500＋900−1,200＝1,200。増加運転資金＝1,200−1,000＝200百万円。3科目の増加をすべて足すと700、仕入債務の増加を引き忘れると400になる。この200が運転資金融資の必要額の目安。"},
{d:8,q:"流動資産4,200百万円、流動負債3,000百万円のとき、正味運転資本はどれか。",c:["1,200百万円","7,200百万円","1,400百万円","2,100百万円","800百万円"],a:0,e:"正味運転資本＝流動資産−流動負債＝4,200−3,000＝1,200百万円。流動比率（140%）と同じ数字を使うが、比率ではなく金額で短期の支払余力を見る。プラスなら流動負債を流動資産で賄えている。"},
{d:8,q:"現金及び預金900百万円、有価証券（流動資産）300百万円、投資有価証券400百万円、年間売上高14,400百万円のとき、手元流動性比率（月）はどれか（小数点以下第2位を四捨五入）。",c:["1.0か月","1.3か月","0.8か月","12.0か月","0.1か月"],a:0,e:"手元流動性＝現金及び預金＋有価証券＝900＋300＝1,200（投資有価証券は含めない）。月商＝14,400÷12＝1,200。手元流動性比率＝1,200÷1,200＝1.0か月。投資有価証券を含めると1.3か月、現金及び預金だけだと0.8か月。"},
{d:8,q:"短期借入金700百万円、長期借入金1,100百万円、年間売上高7,200百万円のとき、借入金月商倍率はどれか（小数点以下第2位を四捨五入）。",c:["3.0か月","1.2か月","1.8か月","0.3か月","36.0か月"],a:0,e:"借入金合計＝700＋1,100＝1,800。月商＝7,200÷12＝600。借入金月商倍率＝1,800÷600＝3.0か月。短期借入金だけだと1.2か月、長期借入金だけだと1.8か月。月商の何か月分の借入があるかを示し、3か月以内が一つの目安、6か月超は過大とされる。"},
{d:8,q:"有利子負債2,400百万円、営業利益300百万円、減価償却費100百万円のとき、債務償還年数＝有利子負債÷（営業利益＋減価償却費）として計算した債務償還年数はどれか（小数点以下第2位を四捨五入）。",c:["6.0年","8.0年","24.0年","4.0年","0.2年"],a:0,e:"債務償還年数＝2,400÷（300＋100）＝2,400÷400＝6.0年。営業利益だけで割ると8.0年、減価償却費だけで割ると24.0年。定義は問題文の指示に従う（当期純利益＋減価償却費で割る流儀もある）。10年以内が一つの目安。"},
{d:8,q:"流動資産3,000百万円、流動負債2,000百万円の会社が、買掛金500百万円を現金で支払った。支払後の流動比率はどれか（小数点以下第2位を四捨五入）。",c:["166.7%","150.0%","125.0%","175.0%","100.0%"],a:0,e:"支払後は流動資産2,500（現金−500）、流動負債1,500（買掛金−500）。流動比率＝2,500÷1,500×100＝166.7%（支払前は150.0%）。流動比率が100%超のとき、流動資産と流動負債を同額減らすと比率は上昇する。"},
{d:8,q:"当座資産に含まれるものの組み合わせとして正しいものはどれか。",c:["現金及び預金・受取手形・売掛金・有価証券","現金及び預金・受取手形・売掛金・棚卸資産","現金及び預金・売掛金・前払費用・短期貸付金","現金及び預金・有価証券・投資有価証券・棚卸資産","受取手形・売掛金・棚卸資産・前渡金"],a:0,e:"当座資産＝現金及び預金＋受取手形＋売掛金（電子記録債権）＋有価証券。すぐに現金化できる資産で、貸倒引当金は控除する。棚卸資産・前払費用・前渡金・その他の流動資産は含めない。当座比率＝当座資産÷流動負債×100。"},
{d:8,q:"固定長期適合率が100%を超えている状態の説明として正しいものはどれか。",c:["固定資産の一部を流動負債（短期資金）で賄っており、資金繰りが不安定になりやすい","固定資産をすべて自己資本で賄っており、極めて安全である","固定負債が自己資本より大きいことを示す","流動比率が200%を超えていることを示す","有利子負債がゼロであることを示す"],a:0,e:"固定長期適合率＝固定資産÷（自己資本＋固定負債）×100。100%超は長期資金で固定資産を賄いきれず、不足分を短期借入などの流動負債で埋めている状態。このとき流動比率は必ず100%未満になる。100%以下が必須ライン。"},
{d:8,q:"安全性の指標の「望ましい方向」の組み合わせとして正しいものはどれか。",c:["流動比率・自己資本比率は高いほど安全、固定比率・負債比率は低いほど安全","流動比率・自己資本比率は低いほど安全、固定比率・負債比率は高いほど安全","流動比率・固定比率はともに高いほど安全","自己資本比率・負債比率はともに高いほど安全","当座比率・固定長期適合率はともに高いほど安全"],a:0,e:"分子が「払う力」（流動資産・当座資産・自己資本）なら高いほど安全。分母が「返す側」（自己資本・長期資金）で分子が固定資産・負債なら低いほど安全。固定比率と負債比率の向きを逆にした選択肢が定番のひっかけ。"},
{d:8,q:"所要運転資金が増加する要因として、誤っているものはどれか。",c:["仕入債務回転期間の長期化","売上高の増加","売上債権回転期間の長期化","棚卸資産回転期間の長期化","仕入先からの現金仕入への切替え要請"],a:0,e:"所要運転資金＝売上債権＋棚卸資産−仕入債務。仕入債務回転期間の長期化（支払を待ってもらう）は仕入債務が増えるので運転資金は減少する。売上増加、回収の遅れ、在庫の滞留、支払条件の短縮（現金仕入化）はいずれも運転資金を増やす。"},
{d:8,q:"有利子負債に含まれないものはどれか。",c:["買掛金","短期借入金","1年内返済予定の長期借入金","社債","長期借入金"],a:0,e:"有利子負債は利息を支払う負債＝短期借入金・1年内返済予定の長期借入金・長期借入金・社債（指示があれば割引手形・リース債務も）。買掛金・支払手形・未払金・引当金は無利子なので含めない。有利子負債依存度・借入金月商倍率の分子になる。"},
{d:8,q:"インタレスト・カバレッジ・レシオの説明として正しいものはどれか。",c:["営業利益に受取利息・受取配当金を加えた額が支払利息の何倍あるかを示し、高いほど利息の支払余力が大きい","支払利息を営業利益で割った比率で、高いほど安全である","有利子負債を営業利益で割った年数で、短いほど安全である","経常利益を総資本で割った比率で、高いほど収益性が高い","当期純利益を支払利息で割った比率で、低いほど安全である"],a:0,e:"インタレスト・カバレッジ・レシオ＝（営業利益＋受取利息・受取配当金）÷支払利息（倍）。利息を本業と金融収益でどれだけ余裕をもって払えるかを見る。1倍未満は利息を稼げていない状態で、与信上の警戒ライン。"},
{d:8,q:"安全性分析で用いる「自己資本」の範囲として正しいものはどれか。",c:["純資産から新株予約権と非支配株主持分を除いたもの（株主資本＋評価・換算差額等）","純資産に長期借入金を加えたもの","資本金と資本剰余金の合計で、利益剰余金は含まない","総資本から流動負債を差し引いたもの","純資産に新株予約権を加え、自己株式を含めないもの"],a:0,e:"自己資本＝株主資本（資本金・資本剰余金・利益剰余金・自己株式）＋評価・換算差額等＝純資産−新株予約権−非支配株主持分。問題文に「純資産を自己資本とみなす」とあればその指示が優先する。"},
{d:8,q:"流動比率と当座比率の一般的な目安の組み合わせとして正しいものはどれか。",c:["流動比率は200%以上が理想、当座比率は100%以上が目安","流動比率は100%以下が理想、当座比率は50%以下が目安","流動比率は50%以上が理想、当座比率は200%以上が目安","流動比率・当座比率とも10%以上が目安","流動比率は高いほど危険、当座比率は低いほど安全"],a:0,e:"流動比率は200%が理想で100%割れは要注意、当座比率は在庫を除いた厳しめの基準で100%が目安。ただし業種で水準が異なり、同業比較・時系列比較で判断する。"},
{d:8,q:"固定比率が100%以下である状態の説明として正しいものはどれか。",c:["固定資産を自己資本の範囲内で賄えており、長期の安全性が高い","固定資産が固定負債より小さいことを示す","流動資産が流動負債より小さいことを示す","自己資本がゼロであることを示す","固定資産の一部を短期借入金で賄っていることを示す"],a:0,e:"固定比率＝固定資産÷自己資本×100。100%以下なら固定資産が自己資本より小さく、返済不要の資金で長期資産をすべて賄えている理想の状態。100%超でも固定長期適合率が100%以下なら長期資金の範囲内として許容される。"},
{d:8,q:"借入金月商倍率の説明として正しいものはどれか。",c:["有利子負債が月商（売上高÷12）の何か月分にあたるかを示し、大きいほど借入負担が重い","月商を有利子負債で割った回転率で、大きいほど借入負担が重い","有利子負債を総資本で割った比率で、%で表す","支払利息を月商で割った比率で、小さいほど安全","借入金を従業員数で割った1人当たり借入額"],a:0,e:"借入金月商倍率＝有利子負債÷（売上高÷12）（月）。売上規模に対する借入の重さを示し、3か月以内が一つの目安、6か月を超えると過大とされる。有利子負債÷総資本は有利子負債依存度（%）。"},

/* ===== Set 9: 損益分岐点と生産性・成長性 ===== */
{d:9,q:"売上高5,000百万円、変動費3,000百万円、固定費1,500百万円のとき、損益分岐点売上高はどれか。",c:["3,750百万円","2,500百万円","1,500百万円","3,000百万円","4,500百万円"],a:0,e:"変動費率＝3,000÷5,000＝0.6、限界利益率＝1−0.6＝0.4。損益分岐点売上高＝固定費÷（1−変動費率）＝1,500÷0.4＝3,750百万円。変動費率で割ると2,500になり誤り。検算：3,750×0.4＝1,500＝固定費。"},
{d:9,q:"売上高8,000百万円、変動費5,600百万円のとき、限界利益率はどれか（小数点以下第2位を四捨五入）。",c:["30.0%","70.0%","42.9%","28.6%","3.0%"],a:0,e:"限界利益＝売上高−変動費＝8,000−5,600＝2,400。限界利益率＝2,400÷8,000×100＝30.0%（＝1−変動費率0.7）。70.0%は変動費率。限界利益を変動費で割ると42.9%になり誤り。"},
{d:9,q:"売上高6,000百万円、固定費2,100百万円、変動費率60%のとき、損益分岐点比率はどれか（小数点以下第2位を四捨五入）。",c:["87.5%","12.5%","114.3%","35.0%","58.3%"],a:0,e:"損益分岐点売上高＝2,100÷（1−0.6）＝5,250。損益分岐点比率＝損益分岐点売上高÷売上高×100＝5,250÷6,000×100＝87.5%。12.5%は安全余裕率（100−87.5）、114.3%は逆数。固定費を変動費率で割ると3,500で58.3%になり誤り。"},
{d:9,q:"売上高10,000百万円、損益分岐点売上高8,500百万円のとき、安全余裕率はどれか（小数点以下第2位を四捨五入）。",c:["15.0%","85.0%","17.6%","1.5%","115.0%"],a:0,e:"安全余裕率＝（売上高−損益分岐点売上高）÷売上高×100＝（10,000−8,500）÷10,000×100＝15.0%。85.0%は損益分岐点比率。分母を損益分岐点売上高にすると17.6%になり誤り。売上が15%落ちると利益ゼロ、という耐久力を示す。"},
{d:9,q:"固定費2,400百万円、変動費率70%のとき、目標利益600百万円を達成するために必要な売上高はどれか。",c:["10,000百万円","8,000百万円","4,286百万円","3,000百万円","12,000百万円"],a:0,e:"目標利益達成売上高＝（固定費＋目標利益）÷（1−変動費率）＝（2,400＋600）÷0.3＝10,000百万円。固定費だけで計算すると8,000（損益分岐点売上高）、変動費率0.7で割ると4,286になり誤り。"},
{d:9,q:"売上高9,000百万円、損益分岐点売上高7,200百万円、変動費率55%のとき、固定費はどれか。",c:["3,240百万円","3,960百万円","4,050百万円","1,800百万円","4,950百万円"],a:0,e:"損益分岐点売上高＝固定費÷（1−変動費率）なので、固定費＝損益分岐点売上高×限界利益率＝7,200×0.45＝3,240百万円。変動費率を掛けると3,960、実際の売上高に掛けると4,050（これは限界利益）、売上高との差1,800は限界利益のうち利益に回る部分。"},
{d:9,q:"売上高が最高の月は売上高10,000百万円・総費用8,200百万円、最低の月は売上高6,000百万円・総費用5,800百万円であった。高低点法による月間固定費はどれか。",c:["2,200百万円","2,400百万円","1,800百万円","2,600百万円","4,000百万円"],a:0,e:"変動費率＝（8,200−5,800）÷（10,000−6,000）＝2,400÷4,000＝0.6。固定費＝8,200−10,000×0.6＝2,200百万円（最低点でも5,800−6,000×0.6＝2,200で一致）。2,400は費用差額そのもの、4,000は売上高差額で誤り。"},
{d:9,q:"限界利益率40%の会社で、固定費が変わらないまま売上高が500百万円増加した場合、利益の増加額はどれか。",c:["200百万円","500百万円","300百万円","125百万円","800百万円"],a:0,e:"固定費が不変なら、売上増加額×限界利益率がそのまま利益の増加になる。500×0.4＝200百万円。変動費率（60%）を掛けた300は変動費の増加額。売上高がそのまま利益にはならない。"},
{d:9,q:"売上高20,000百万円、材料費8,000百万円、外注加工費2,000百万円、購入部品費1,000百万円（いずれも外部購入価値）のとき、控除法による付加価値はどれか。",c:["9,000百万円","12,000百万円","10,000百万円","11,000百万円","8,000百万円"],a:0,e:"付加価値（控除法）＝売上高−外部購入価値＝20,000−（8,000＋2,000＋1,000）＝9,000百万円。材料費だけ引くと12,000、購入部品費を引き忘れると10,000。11,000は外部購入価値の合計そのもの。"},
{d:9,q:"付加価値9,000百万円、売上高20,000百万円、人件費5,400百万円、従業員数150人のとき、労働生産性（従業員1人当たり付加価値）はどれか（小数点以下第2位を四捨五入）。",c:["60.0百万円","133.3百万円","36.0百万円","24.0百万円","90.0百万円"],a:0,e:"労働生産性＝付加価値÷従業員数＝9,000÷150＝60.0百万円。売上高で計算すると133.3百万円（1人当たり売上高）、人件費で計算すると36.0百万円（1人当たり人件費）。"},
{d:9,q:"人件費5,400百万円、付加価値9,000百万円、売上高20,000百万円のとき、労働分配率はどれか（小数点以下第2位を四捨五入）。",c:["60.0%","27.0%","166.7%","45.0%","40.0%"],a:0,e:"労働分配率＝人件費÷付加価値×100＝5,400÷9,000×100＝60.0%。分母を売上高にすると27.0%（売上高人件費率）で誤り。逆数は166.7%、45.0%は付加価値率（9,000÷20,000）。"},
{d:9,q:"有形固定資産6,000百万円（うち建設仮勘定600百万円）、従業員数120人のとき、建設仮勘定を除いて計算した労働装備率はどれか。",c:["45百万円","50百万円","5百万円","55百万円","40百万円"],a:0,e:"労働装備率＝有形固定資産（建設仮勘定を除く）÷従業員数＝（6,000−600）÷120＝45百万円。建設仮勘定を含めると50百万円、建設仮勘定だけで計算すると5百万円。稼働中の設備だけで従業員1人当たりの装備を見る。指示がなければ有形固定資産合計で計算する。"},
{d:9,q:"労働装備率30百万円、設備生産性（付加価値÷有形固定資産）1.8のとき、労働生産性はどれか（小数点以下第2位を四捨五入）。",c:["54.0百万円","16.7百万円","31.8百万円","48.0百万円","60.0百万円"],a:0,e:"労働生産性＝労働装備率×設備生産性＝（有形固定資産÷従業員数）×（付加価値÷有形固定資産）＝付加価値÷従業員数。30×1.8＝54.0百万円。割ると16.7、足すと31.8になり誤り。"},
{d:9,q:"前期売上高8,000百万円、当期売上高9,200百万円のとき、売上高増加率はどれか（小数点以下第2位を四捨五入）。",c:["15.0%","13.0%","115.0%","1.2%","12.0%"],a:0,e:"売上高増加率＝（当期売上高−前期売上高）÷前期売上高×100＝1,200÷8,000×100＝15.0%。分母を当期にすると13.0%、当期÷前期は115.0%（増加率ではなく対前期比）。増加率の分母は必ず前期。"},
{d:9,q:"前期経常利益400百万円、当期経常利益340百万円のとき、経常利益増加率はどれか（小数点以下第2位を四捨五入）。",c:["−15.0%","−17.6%","15.0%","85.0%","−60.0%"],a:0,e:"経常利益増加率＝（340−400）÷400×100＝−60÷400×100＝−15.0%。分母を当期にすると−17.6%、85.0%は当期÷前期。マイナスなので減益。売上が伸びていれば増収減益。"},
{d:9,q:"前期は販売単価100円・単位原価70円・販売数量1,000個、当期は販売単価95円・単位原価72円・販売数量1,200個であった。販売数量差異を（当期数量−前期数量）×（前期単価−前期単位原価）で計算した場合、販売数量の増加による売上総利益の増加額はどれか。",c:["6,000円","4,600円","−6,000円","−2,400円","2,400円"],a:0,e:"販売数量差異＝（1,200−1,000）×（100−70）＝200×30＝＋6,000円。当期の単位利益23円で計算すると4,600になる（計算方法は問題の指示に従う）。販売価格差異＝（95−100）×1,200＝−6,000、原価差異＝（70−72）×1,200＝−2,400、合計−2,400は売上総利益30,000→27,600の減少と一致する。"},
{d:9,q:"損益分岐点の説明として正しいものはどれか。",c:["売上高と総費用（変動費＋固定費）が等しくなり、利益がゼロになる売上高","変動費と固定費が等しくなる売上高","売上高が固定費と等しくなる売上高","限界利益がゼロになる売上高","営業利益と経常利益が等しくなる売上高"],a:0,e:"損益分岐点は売上高＝変動費＋固定費、すなわち限界利益＝固定費となる点。限界利益がゼロになるのは売上高がゼロのとき。損益分岐点売上高＝固定費÷（1−変動費率）。"},
{d:9,q:"一般に変動費に分類される費用の組み合わせとして正しいものはどれか。",c:["材料費・商品仕入高・外注加工費・販売手数料","減価償却費・地代家賃・保険料・支払利息","役員報酬・減価償却費・固定資産税","材料費・減価償却費・地代家賃","支払利息・販売手数料・保険料"],a:0,e:"変動費は売上高（操業度）に比例して増減する費用：材料費・仕入高・外注加工費・販売手数料・荷造運賃など。減価償却費・地代家賃・保険料・固定給の人件費・支払利息は売上がゼロでもかかる固定費。"},
{d:9,q:"損益分岐点売上高を引き下げる方法として、誤っているものはどれか。",c:["変動費率を引き上げる","固定費を削減する","変動費率を引き下げる","限界利益率を引き上げる","販売単価を引き上げて変動費は据え置く"],a:0,e:"損益分岐点売上高＝固定費÷（1−変動費率）。固定費の削減か、変動費率の引下げ（＝限界利益率の引上げ）で下がる。変動費率を引き上げると分母が小さくなり損益分岐点は上がる。単価引上げで変動費据え置きなら変動費率は下がる。"},
{d:9,q:"損益分岐点比率と安全余裕率の関係として正しいものはどれか。",c:["安全余裕率＝100%−損益分岐点比率であり、損益分岐点比率が低いほど安全性が高い","安全余裕率＝損益分岐点比率であり、両者は同じ意味である","安全余裕率＝100%＋損益分岐点比率である","損益分岐点比率が高いほど安全性が高い","損益分岐点比率が100%を超えると安全余裕率もプラスになる"],a:0,e:"損益分岐点比率＝損益分岐点売上高÷売上高×100、安全余裕率＝（売上高−損益分岐点売上高）÷売上高×100＝100%−損益分岐点比率。損益分岐点比率100%超は損益分岐点に売上が届いていない＝赤字で、安全余裕率はマイナス。"},
{d:9,q:"加算法（中小企業庁方式）による付加価値の構成項目の組み合わせとして正しいものはどれか。",c:["人件費・減価償却費・賃借料・租税公課・金融費用（支払利息）・経常利益","材料費・外注加工費・購入部品費・商品仕入高","売上高・売上原価・販売費及び一般管理費","人件費・材料費・売上総利益","減価償却費・支払利息・法人税等・当期純利益"],a:0,e:"加算法は企業内部で生み出した価値を積み上げる：人件費＋減価償却費＋賃借料＋租税公課＋金融費用＋経常利益（中小企業庁方式）。材料費・外注加工費などの外部購入価値は控除法で売上高から差し引く側。定義は流儀があるので問題文の指定に従う。"},
{d:9,q:"労働生産性の分解式として正しいものはどれか。",c:["労働生産性 ＝ 労働装備率 × 設備生産性（付加価値÷有形固定資産）","労働生産性 ＝ 労働分配率 × 付加価値率","労働生産性 ＝ 労働装備率 ÷ 設備生産性","労働生産性 ＝ 1人当たり売上高 × 労働分配率","労働生産性 ＝ 総資本回転率 × 売上高経常利益率"],a:0,e:"労働生産性（付加価値÷従業員数）＝有形固定資産÷従業員数（労働装備率）×付加価値÷有形固定資産（設備生産性）。有形固定資産が約分で消える。もう一つの分解は1人当たり売上高×付加価値率。"},
{d:9,q:"労働分配率が前期より上昇した場合の解釈として、最も適切なものはどれか。",c:["人件費の増加率が付加価値の増加率を上回っており、放置すれば利益を圧迫する","付加価値が人件費より速く伸びており、収益性が改善している","従業員1人当たりの設備が増えたことを示す","売上高が増加したことを直接示す","固定費が減少したことを示す"],a:0,e:"労働分配率＝人件費÷付加価値×100。上昇は付加価値に対して人件費の割合が高まった状態（賃上げ・増員、または付加価値の減少）。高すぎると利益が残らない。設備の増加は労働装備率の話。"},
{d:9,q:"「増収減益」の説明として正しいものはどれか。",c:["売上高は前期より増加したが、利益は前期より減少した","売上高も利益も前期より増加した","売上高は前期より減少したが、利益は前期より増加した","売上高も利益も前期より減少した","売上高は変わらず、利益だけが増加した"],a:0,e:"「収」は売上高、「益」は利益。増収減益は値引き販売や原価・固定費の増加で起きる。減収増益はコスト削減や不採算部門の撤退で起きる。増収でも運転資金が膨らむと資金繰りは苦しくなることがある。"},
{d:9,q:"営業レバレッジ（限界利益÷営業利益）の説明として正しいものはどれか。",c:["売上高の変化率に対して営業利益が何倍の率で変化するかを示し、固定費の割合が大きい企業ほど大きくなる","固定費を売上高で割った比率で、小さいほど利益の変動が大きい","有利子負債を自己資本で割った倍率で、大きいほど金利負担が重い","変動費率の逆数で、大きいほど損益分岐点が低い","営業利益を総資本で割った比率で、収益性を示す"],a:0,e:"営業レバレッジ＝限界利益÷営業利益。例えば限界利益3,000・営業利益1,000なら3倍で、売上高が10%増えると営業利益は30%増える。固定費が重い（限界利益と営業利益の差が大きい）会社ほど利益の振れ幅が大きい。"},

/* ===== Set 10: 資金の分析 ===== */
{d:10,q:"当期の資料：当期純利益300百万円、減価償却費200百万円、増資100百万円、長期借入金の借入400百万円、配当金の支払100百万円、固定資産の取得700百万円。資金運用表における固定資金の調達合計はどれか。",c:["1,000百万円","600百万円","800百万円","900百万円","1,100百万円"],a:0,e:"固定資金の調達＝当期純利益300＋減価償却費200＋増資100＋長期借入金の借入400＝1,000百万円。配当金と固定資産の取得は運用側。減価償却費を落とすと800、長期借入を落とすと600、配当を調達に入れると1,100で誤り。"},
{d:10,q:"当期の資料：固定資産の取得800百万円、長期借入金の返済300百万円、配当金の支払100百万円、減価償却費250百万円、当期純利益350百万円。資金運用表における固定資金の運用合計はどれか。",c:["1,200百万円","1,450百万円","1,100百万円","900百万円","1,050百万円"],a:0,e:"固定資金の運用＝固定資産の取得800＋長期借入金の返済300＋配当金100＝1,200百万円。減価償却費と当期純利益は調達側なので含めない。減価償却費を運用に入れると1,450、配当を落とすと1,100になる。"},
{d:10,q:"当期の資料：当期純利益400百万円、減価償却費300百万円、長期借入金の純増加200百万円、固定資産の取得600百万円、配当金の支払100百万円。資金運用表の固定資金の部における余裕額または不足額はどれか。",c:["余裕額200百万円","不足額200百万円","余裕額500百万円","不足額100百万円","余裕額300百万円"],a:0,e:"固定資金の調達＝400＋300＋200＝900、運用＝600＋100＝700。固定資金の余裕額＝900−700＝200百万円（プラスなので余裕）。この余裕額が運転資金の部の調達に回る。減価償却費を調達に入れ忘れると不足額100になる。"},
{d:10,q:"当期において売上債権が300百万円増加、棚卸資産が200百万円増加、仕入債務が150百万円増加した。資金運用表の運転資金の部における資金の不足額（運用超過額）はどれか。",c:["350百万円","650百万円","150百万円","500百万円","50百万円"],a:0,e:"運転資金の部の運用＝売上債権の増加300＋棚卸資産の増加200＝500、調達＝仕入債務の増加150。不足額＝500−150＝350百万円（＝所要運転資金の増加額）。仕入債務の増加を運用に入れると650、売上債権だけを見ると150になる。"},
{d:10,q:"資金運用表において、運転資金の部の不足額が350百万円、固定資金の部の余裕額が200百万円、短期借入金の増加が100百万円であった。現金預金の部で読み取れる現金預金の増減額はどれか。",c:["減少50百万円","減少150百万円","減少250百万円","増加100百万円","減少450百万円"],a:0,e:"運転資金の不足350のうち固定資金の余裕200で賄い、残り150を現金預金の部で調達する。短期借入金の増加100では50足りないので、現金預金が50百万円減少して帳尻が合う。運用合計と調達合計は必ず一致する。"},
{d:10,q:"当期の売上高12,000百万円、売上債権が期首1,800百万円から期末2,000百万円に増加した。資金移動表における経常収入（売上代金の回収額）はどれか。",c:["11,800百万円","12,200百万円","12,000百万円","10,000百万円","13,800百万円"],a:0,e:"経常収入＝売上高−売上債権の増加＝12,000−（2,000−1,800）＝11,800百万円。売上債権が増えた分はまだ現金になっていない。増加を足すと12,200で誤り。売上債権が減少した場合は売上高に加える。"},
{d:10,q:"当期の売上原価8,000百万円、棚卸資産が100百万円増加、仕入債務が300百万円増加した。資金移動表における仕入支出（仕入代金の支払額）はどれか。",c:["7,800百万円","8,400百万円","8,100百万円","7,600百万円","8,200百万円"],a:0,e:"当期仕入高＝売上原価＋棚卸資産の増加＝8,000＋100＝8,100。仕入支出＝仕入高−仕入債務の増加＝8,100−300＝7,800百万円。仕入債務の増加は支払を待ってもらった分なので差し引く。符号を逆にすると8,400、棚卸資産を無視すると7,700になる。"},
{d:10,q:"資金移動表の経常収入10,500百万円、経常支出10,000百万円のとき、経常収支比率はどれか（小数点以下第2位を四捨五入）。",c:["105.0%","95.2%","5.0%","104.8%","0.95%"],a:0,e:"経常収支比率＝経常収入÷経常支出×100＝10,500÷10,000×100＝105.0%。逆にすると95.2%。100%超なら本業の収入で本業の支出を賄えている。5.0%は（収入−支出）÷支出。"},
{d:10,q:"資金繰表において、前月繰越300百万円、当月の経常収入2,000百万円、経常支出2,200百万円、借入金の借入150百万円、借入金の返済100百万円であった。翌月繰越はどれか。",c:["150百万円","100百万円","250百万円","50百万円","350百万円"],a:0,e:"翌月繰越＝前月繰越＋経常収入−経常支出＋財務収入−財務支出＝300＋2,000−2,200＋150−100＝150百万円。経常収支はマイナス200で、借入で穴埋めしている形。これが続けば資金繰りは悪化する。"},
{d:10,q:"有形固定資産（帳簿価額）が期首5,000百万円、期末5,400百万円で、当期の減価償却費は600百万円、固定資産の売却はなかった。当期の固定資産取得額（資金運用表の固定資金の運用に計上する額）はどれか。",c:["1,000百万円","400百万円","200百万円","600百万円","1,600百万円"],a:0,e:"期末帳簿価額＝期首＋取得−減価償却費なので、取得額＝5,400−5,000＋600＝1,000百万円。B/S上の純増400だけを運用にすると減価償却費が漏れる。資金運用表では減価償却費600を調達、取得額1,000を運用に総額で表示する。"},
{d:10,q:"長期借入金が期首2,000百万円、期末2,300百万円で、当期の返済額は500百万円であった。当期の新規借入額はどれか。",c:["800百万円","300百万円","200百万円","500百万円","1,300百万円"],a:0,e:"期末＝期首＋新規借入−返済なので、新規借入＝2,300−2,000＋500＝800百万円。資金運用表で総額表示するなら借入800を固定資金の調達、返済500を固定資金の運用に計上する（純額なら増加300を調達）。"},
{d:10,q:"利益剰余金が期首1,000百万円、期末1,250百万円で、当期純利益は350百万円であった（配当以外の変動はない）。当期の配当金の支払額はどれか。",c:["100百万円","250百万円","350百万円","600百万円","150百万円"],a:0,e:"期末利益剰余金＝期首＋当期純利益−配当なので、配当＝1,000＋350−1,250＝100百万円。資金運用表では当期純利益350を固定資金の調達、配当100を固定資金の運用に分けて表示する。250は利益剰余金の純増額。"},
{d:10,q:"税引前当期純利益500百万円、減価償却費200百万円、売上債権の増加100百万円、棚卸資産の減少50百万円、仕入債務の減少80百万円、法人税等の支払額150百万円のとき、間接法による営業活動によるキャッシュ・フローはどれか（他の調整項目はないものとする）。",c:["420百万円","570百万円","320百万円","580百万円","620百万円"],a:0,e:"営業CF＝500＋200（非資金費用）−100（売上債権増加）＋50（棚卸資産減少）−80（仕入債務減少）−150（法人税等支払）＝420百万円。売上債権の増加はマイナス、棚卸資産の減少はプラス、仕入債務の減少はマイナス。法人税を忘れると570、仕入債務の符号を逆にすると580。"},
{d:10,q:"営業活動によるキャッシュ・フロー800百万円、投資活動によるキャッシュ・フロー△500百万円、財務活動によるキャッシュ・フロー△200百万円のとき、簡便法（営業CF＋投資CF）によるフリー・キャッシュ・フローはどれか。",c:["300百万円","100百万円","1,300百万円","△300百万円","500百万円"],a:0,e:"フリー・キャッシュ・フロー＝営業CF＋投資CF＝800＋（−500）＝300百万円。財務CFは含めない（含めると100）。投資CFの符号を逆にすると1,300。フリーCFは借入返済や配当に自由に使える資金で、プラスが続くことが望ましい。"},
{d:10,q:"資金運用表の区分と並び順として正しいものはどれか。",c:["固定資金の部 → 運転資金の部 → 現金預金の部","運転資金の部 → 固定資金の部 → 現金預金の部","現金預金の部 → 固定資金の部 → 運転資金の部","営業活動の部 → 投資活動の部 → 財務活動の部","経常収支の部 → 設備等収支の部 → 財務収支の部"],a:0,e:"資金運用表は固定資金の部（長期の調達と運用）→運転資金の部→現金預金の部の3区分。固定資金の余裕額が運転資金に流れ、運転資金の過不足が現金預金の部で調整される構造。営業・投資・財務はC/F計算書、経常・設備等・財務収支は資金移動表の区分。"},
{d:10,q:"資金運用表において減価償却費を固定資金の調達に計上する理由として正しいものはどれか。",c:["費用として利益から差し引かれているが現金の支出を伴わないため、その分の資金が企業内部に留保されているから","減価償却費は銀行からの借入で賄われるから","減価償却費は固定資産の売却収入だから","減価償却費は当期純利益に含まれていないから","減価償却費は配当の原資になるから"],a:0,e:"減価償却費は非資金費用。当期純利益は減価償却費を引いた後の数字なので、資金ベースに戻すために当期純利益に加える。「当期純利益＋減価償却費」が内部留保による資金の調達額（簡易キャッシュ・フロー）で、設備資金の返済原資の目安になる。"},
{d:10,q:"資金運用表における配当金の支払の区分として正しいものはどれか。",c:["固定資金の部の運用","固定資金の部の調達","運転資金の部の運用","運転資金の部の調達","現金預金の部の調達"],a:0,e:"利益剰余金の増減は「当期純利益−配当」の純額なので、当期純利益を固定資金の調達、配当金の支払を固定資金の運用に分けて総額で表示する。配当は社外流出であり、資金の使いみち（運用）。"},
{d:10,q:"資金運用表において「売上債権の増加」はどの区分に計上されるか。",c:["運転資金の部の運用","運転資金の部の調達","固定資金の部の運用","固定資金の部の調達","現金預金の部の調達"],a:0,e:"資産の増加は資金の運用。売上債権の増加は売上代金がまだ回収されていない分だけ資金が寝ている状態なので、運転資金の部の運用に計上する。売上債権が減少すれば調達側。"},
{d:10,q:"資金運用表において「仕入債務の増加」はどの区分に計上されるか。",c:["運転資金の部の調達","運転資金の部の運用","固定資金の部の調達","固定資金の部の運用","現金預金の部の運用"],a:0,e:"負債の増加は資金の調達。仕入債務の増加は仕入先に支払を待ってもらっている分だけ資金を調達したのと同じなので、運転資金の部の調達。仕入債務の減少なら運用側になる。"},
{d:10,q:"資金運用表で固定資金の部が不足額（運用が調達を上回る）となっている場合の解釈として、最も適切なものはどれか。",c:["設備投資などの長期の資金需要を運転資金や短期借入金で賄っており、固定長期適合率の悪化と同じ意味で資金繰りが不安定になりやすい","長期資金に余裕があり、運転資金の増加に充てられる望ましい状態である","現金預金が増加していることを示す","売上債権が減少していることを示す","当期純利益が減価償却費を上回っていることを示す"],a:0,e:"固定資金の不足＝固定資産取得・借入返済・配当を当期純利益・減価償却費・長期借入などで賄いきれず、短期資金（運転資金・短期借入・現金預金の取崩し）に頼っている状態。固定長期適合率100%超と同じ構造で、借換えが止まれば行き詰まる。"},
{d:10,q:"資金移動表と資金運用表の違いとして正しいものはどれか。",c:["資金移動表は損益計算書の収益・費用を組み込み、経常収支・設備等収支・財務収支の収支形式で資金の動きを示す","資金移動表は貸借対照表の増減だけを用い、損益計算書は使わない","資金運用表は月次の現金の出入りを予定と実績で示す表である","資金移動表は営業活動・投資活動・財務活動の3区分で作成する法定の書類である","両者に違いはなく、名称が異なるだけである"],a:0,e:"資金運用表は2期のB/S増減から調達と運用を示す。資金移動表はP/Lの売上高・仕入・経費をB/S増減で現金ベースに直し、経常収支・設備等収支（固定資産等収支）・財務収支に組み替える。月次の予定・実績は資金繰表。営業・投資・財務の3区分はC/F計算書。"},
{d:10,q:"経常収支比率が継続して100%を下回っている企業の説明として、最も適切なものはどれか。",c:["本業の収入で本業の支出を賄えておらず、借入などで不足を補っている状態で、資金繰り悪化の兆候である","本業の収入が支出を上回り、資金に余裕がある状態である","損益計算書上は必ず赤字である","固定資産の投資が過小である","自己資本比率が高いことを示す"],a:0,e:"経常収支比率＝経常収入÷経常支出×100。100%未満は経常収支が赤字で、設備投資や返済に回す資金が本業から生まれていない。P/Lが黒字でも売上債権・在庫の膨張で経常収支が赤字になることがある（黒字倒産の入口）。"},
{d:10,q:"資金繰表に関する記述のうち、正しいものはどれか。",c:["前月繰越に当月の収入を加え支出を差し引いて翌月繰越を求め、経常収支・経常外収支・財務収支に区分して示すのが一般的である","資金繰表は決算日時点の財政状態を示す法定の計算書類である","資金繰表は実績のみを記載し、予定を記載することはない","経常収支の赤字を短期借入の借換えで補い続けても資金繰り上の問題はない","資金繰表は発生主義で作成され、現金の出入りは反映しない"],a:0,e:"資金繰表は現金の出入りを月次などで追う表（現金主義）。実績資金繰表と予定資金繰表があり、経常収支（売上回収・仕入支払・経費）・経常外収支（設備・税金など）・財務収支（借入・返済）に分ける。経常収支の赤字を借換えで補い続けるのは資金繰り悪化の典型的なサイン。"},
{d:10,q:"資金移動表の各区分とキャッシュ・フロー計算書の区分の対応として正しいものはどれか。",c:["経常収支≒営業活動によるCF、設備等収支≒投資活動によるCF、財務収支≒財務活動によるCF","経常収支≒投資活動によるCF、設備等収支≒営業活動によるCF","経常収支≒財務活動によるCF、財務収支≒営業活動によるCF","設備等収支≒営業活動によるCF、財務収支≒投資活動によるCF","資金移動表とキャッシュ・フロー計算書に対応関係はない"],a:0,e:"資金移動表の経常収支は本業の現金収支（≒営業CF）、設備等収支は固定資産の取得・売却（≒投資CF）、財務収支は借入・返済・増資・配当（≒財務CF）。3区分の合計が現金預金の増減になる点も同じ。"},
{d:10,q:"融資判断における資金使途と返済原資の対応として、最も適切なものはどれか。",c:["設備資金の返済原資は当期純利益＋減価償却費（簡易キャッシュ・フロー）であり、増加運転資金は売上増加に伴う正常な需要か回収遅れ・在庫滞留による後ろ向きの需要かを回転期間で見極める","設備資金の返済原資は売上債権の回収であり、運転資金の返済原資は減価償却費である","運転資金の増加はすべて後ろ向きの資金需要であり、融資すべきでない","返済原資は自己資本比率だけで判断できる","設備資金は短期借入で調達するのが望ましい"],a:0,e:"設備資金は長期にわたって利益と減価償却費で回収するので、返済原資は当期純利益＋減価償却費。運転資金は売上増加に伴う増加運転資金（前向き）なら営業循環の中で回収されるが、回転期間の長期化による需要（後ろ向き）は回収の裏付けが弱い。設備資金を短期で借りると固定長期適合率が悪化する。"}
]);
